"use client";

import React, { useEffect, useState } from "react";
import Link from "next/link";
import Image from "next/image";
import { cn } from "@/lib/utils";
import { PublicVideoDTO } from "@/app/types/video";
import { formatDistanceToNow } from "date-fns";
import { dateFnsLocale } from "@/lib/i18n/date-locale";
import { countedNoun } from "@/lib/i18n/plurals";
import { intlLocale } from "@/lib/i18n/ui";
import { useLanguage } from "./LanguageContext";
import { getVideoDisplayTitle } from "@/lib/video-title-overrides";
import AccessLockOverlay from "./AccessLockOverlay";
import { NajsIcon } from "./najs/primitives";
import { getLocalizedHref, appendQueryString } from "@/lib/i18n/routing";
import { toVideoAccessTier } from "@/lib/access-tier";
import VideoTaxonomyChips from "./search/VideoTaxonomyChips";
import { PremiumThumbBadge } from "./premium-pass/PremiumBadge"; // patron zone (docs/architecture/patron-zone.md)

interface ChannelVideoCardProps {
  video: PublicVideoDTO;
  isLoggedIn: boolean;
  /** Position in the grid, used for a staggered mount-in animation. Optional so callers that don't care about ordering can omit it. */
  index?: number;
}

export default function ChannelVideoCard({
  video,
  isLoggedIn,
  index = 0,
}: ChannelVideoCardProps) {
  const { t, language, tx } = useLanguage();
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const displayTitle = getVideoDisplayTitle(video, language);

  // Two levels (lib/access-tier.ts): anything not PUBLIC needs sign-in.
  const tier = toVideoAccessTier(video.tier);
  const hasAccess = tier === "PUBLIC" || isLoggedIn;

  const getAccessBadge = () => {
    if (!mounted) return null;
    if (video.premiumPass) return { text: tx("Patron", "Patron"), variant: "locked" }; // patron zone
    if (tier === "PUBLIC") return { text: tx("Publiczne", "Public"), variant: "public" };
    if (!hasAccess) return { text: tx("Logowanie", "Login"), variant: "locked" };
    return { text: tx("Odblok.", "Unlocked"), variant: "unlocked" };
  };

  const badge = getAccessBadge();
  // patron zone: a pass video shows the PREMIUM plate instead of the sign-in wall.
  const lockState = !hasAccess && !video.premiumPass ? "LOGIN_REQUIRED" : null;

  return (
    <div
      className="channel-video-card group cursor-pointer flex flex-col motion-safe:animate-[polutek-surface-enter_360ms_cubic-bezier(0.16,1,0.3,1)_both]"
      style={{ animationDelay: `${Math.min(index, 8) * 45}ms` }}
    >
      <div className="block relative">
        <Link href={appendQueryString(getLocalizedHref(language, "home"), `v=${video.id}`)} className="absolute inset-0 z-0" />
        <div className="channel-video-card-media relative aspect-video rounded-[13px] bg-black mb-3 z-10 overflow-hidden">
          <div className="relative h-full w-full">
            {video.thumbnailUrl ? (
              <Image
                src={video.thumbnailUrl}
                alt={displayTitle}
                fill
                sizes="(min-width: 1280px) 20vw, (min-width: 640px) 50vw, 100vw"
                className="object-cover opacity-90 transition duration-500 group-hover:scale-105 motion-reduce:transition-none"
              />
            ) : (
              <div className="flex h-full w-full items-center justify-center bg-neutral-900">
                <NajsIcon name="video" className="w-8 h-8" stroke="rgba(255,255,255,0.2)" />
              </div>
            )}
            {lockState && (
              <div className="absolute inset-0 z-20">
                <AccessLockOverlay state={lockState} variant="thumbnailCompact" />
              </div>
            )}
            {video.premiumPass && <PremiumThumbBadge locked />}
            {video.duration && !lockState && (
              <div className="absolute bottom-2 right-2 bg-black/80 text-white text-[12px] font-bold px-1.5 py-0.5 rounded z-30">
                {video.duration}
              </div>
            )}
            {/* 18+ (creator's declaration or moderation): signed-in viewers only */}
            {video.isAdult && !video.premiumPass && (
              <div
                data-testid="adult-badge"
                className="absolute left-2 top-2 z-30 rounded-full bg-red-600 px-2 py-[3px] text-[9px] font-black leading-none tracking-[0.1em] text-white pointer-events-none"
              >
                18+
              </div>
            )}
            {/* Access Indicator Badge on Thumbnail */}
            {badge && (
              <div
                className={cn(
                  "absolute right-2 top-2 z-30 max-w-[92px] truncate rounded-full px-2 py-[3px] text-[9px] font-black uppercase leading-none tracking-[0.14em] pointer-events-none",
                  badge.variant === "public" && "bg-white/92 text-[var(--chan-ink)]",
                  badge.variant === "unlocked" && "bg-[var(--chan-blue-soft)] text-[var(--chan-blue)]",
                  badge.variant === "locked" && "bg-[var(--chan-ink)] text-white",
                )}
              >
                {badge.text}
              </div>
            )}
          </div>
        </div>
        <div className="flex gap-2 relative z-10">
          <div className="flex-1 min-w-0">
            <Link href={appendQueryString(getLocalizedHref(language, "home"), `v=${video.id}`)}>
              <h3 className="font-sans text-[14px] font-bold uppercase tracking-[0.01em] text-[var(--chan-ink)] leading-tight line-clamp-2 mb-1 hover:opacity-80 transition-opacity">
                {displayTitle}
              </h3>
            </Link>
            <div className="font-sans text-[12px] text-[var(--chan-muted)] leading-relaxed">
              <div className="flex items-center gap-1">
                <span>
                  {mounted
                    ? video.views.toLocaleString(intlLocale(language))
                    : video.views}{" "}
                  {mounted ? countedNoun(language, "views", video.views) : t.views}
                </span>
                {video.publishedAt && (
                  <>
                    <span>{"\u2022"}</span>
                    <span>
                      {mounted
                        ? formatDistanceToNow(new Date(video.publishedAt), {
                            addSuffix: true,
                            locale: dateFnsLocale(language),
                          }).replace("około", "ok.")
                        : ""}
                    </span>
                  </>
                )}
              </div>
            </div>
            <VideoTaxonomyChips category={video.category} tags={[]} locale={language} tx={tx} className="mt-1.5" />
          </div>
        </div>
      </div>
    </div>
  );
}

