"use client";

// "Hasło" / "Security" tab of the account panel: password (change, or set one by e-mail link when
// the account only has Google), TOTP two-step verification and the list of signed-in devices.

import React, { useEffect, useState } from "react";
import { QRCodeSVG } from "qrcode.react";
import { Feedback, Field, Primary, ReauthNotice, useAccountUser, useHasPassword } from "./AccountSections";
import { useCaptchaGate } from "./useCaptchaGate";
import { authClient, captchaFetchOptions } from "@/lib/auth/client";
import { authErrorMessage, isSessionNotFresh } from "@/lib/auth/errors";
import { PASSWORD_MIN_LENGTH } from "@/lib/auth/config";
import { refreshSession } from "@/lib/auth/react";
import { intlLocale, type Tx } from "@/lib/i18n/ui";

type Msg = { error: string | null; info: string | null };
const EMPTY: Msg = { error: null, info: null };
const NETWORK_ERROR = { code: "NETWORK_ERROR" } as const;

/**
 * Runs one account action (audit AUTH-08): the spinner always stops, and a dropped connection (the auth
 * client throws on network errors) ends in a readable message instead of a button that spins for ever.
 */
async function guarded(
  setLoading: (value: boolean) => void,
  setMsg: (msg: Msg) => void,
  tx: Tx,
  task: () => Promise<void>,
) {
  setLoading(true);
  setMsg(EMPTY);
  try {
    await task();
  } catch {
    setMsg({ error: authErrorMessage(NETWORK_ERROR, tx), info: null });
  } finally {
    setLoading(false);
  }
}

function PasswordPart({ tx, hasPassword }: { tx: Tx; hasPassword: boolean }) {
  const user = useAccountUser();
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState<Msg>(EMPTY);
  const captchaGate = useCaptchaGate(tx);

  function change(e: React.FormEvent) {
    e.preventDefault();
    return guarded(setLoading, setMsg, tx, async () => {
      const { error } = await authClient.changePassword({ currentPassword, newPassword, revokeOtherSessions: true });
      if (error) return setMsg({ error: authErrorMessage(error, tx), info: null });
      setCurrentPassword("");
      setNewPassword("");
      setMsg({ error: null, info: tx("Hasło zmienione. Pozostałe urządzenia wylogowano.", "Password changed. Other devices were signed out.") });
    });
  }

  function sendSetLink() {
    const email = user.primaryEmailAddress?.emailAddress;
    if (!email || !captchaGate.ready(sendSetLink)) return;
    return guarded(setLoading, setMsg, tx, async () => {
      try {
        const { error } = await authClient.requestPasswordReset({
          email,
          redirectTo: "/reset-password",
          fetchOptions: captchaFetchOptions(captchaGate.token()),
        });
        if (error) return setMsg({ error: authErrorMessage(error, tx), info: null });
        setMsg({ error: null, info: tx("Wysłaliśmy link do ustawienia hasła na Twój e-mail.", "We sent a link to set a password to your email.") });
      } finally {
        captchaGate.reset();
      }
    });
  }

  if (!hasPassword) {
    return (
      <div className="space-y-3">
        <Feedback error={msg.error} info={msg.info} />
        <p className="text-[13px] text-[var(--chan-body)]">
          {tx("Logujesz się przez Google i nie masz jeszcze hasła. Możesz je ustawić linkiem wysłanym na e-mail.", "You sign in with Google and have no password yet. You can set one with a link sent to your email.")}
        </p>
        {captchaGate.widget}
        <button
          type="button"
          onClick={sendSetLink}
          disabled={loading || captchaGate.waiting}
          className="flex h-[44px] w-full items-center justify-center rounded-[12px] bg-[var(--chan-blue)] font-brand text-[15px] font-bold text-white disabled:opacity-60"
        >
          {tx("Wyślij link", "Send link")}
        </button>
      </div>
    );
  }

  return (
    <form onSubmit={change} className="space-y-3">
      <Feedback error={msg.error} info={msg.info} />
      <Field label={tx("Obecne hasło", "Current password")} type="password" value={currentPassword} onChange={setCurrentPassword} autoComplete="current-password" />
      <Field label={tx("Nowe hasło (min. {0} znaków)", "New password (min. {0} characters)", PASSWORD_MIN_LENGTH)} type="password" value={newPassword} onChange={setNewPassword} autoComplete="new-password" />
      <Primary loading={loading} label={tx("Zmień hasło", "Change password")} />
    </form>
  );
}

/** Backup codes with copy and download, shown right after they were generated (they cannot be read again). */
function BackupCodesBox({ codes, tx }: { codes: string[]; tx: Tx }) {
  const [copied, setCopied] = useState(false);
  const text = codes.join("\n");

  async function copy() {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
    } catch {
      setCopied(false);
    }
  }

  function download() {
    const url = URL.createObjectURL(new Blob([`${text}\n`],{ type: "text/plain" }));
    const link = document.createElement("a");
    link.href = url;
    link.download = "pawelperfect-backup-codes.txt";
    link.click();
    URL.revokeObjectURL(url);
  }

  return (
    <div>
      <p className="mb-1 text-[11px] font-bold uppercase tracking-wide text-[var(--chan-muted)]">
        {tx("Kody zapasowe (zapisz je, każdy działa raz)", "Backup codes (save them, each works once)")}
      </p>
      <p className="break-all rounded-lg bg-[var(--chan-surface)] px-3 py-2 font-mono text-[12px]">{codes.join("  ")}</p>
      <div className="mt-2 flex gap-3 text-[12px] font-bold">
        <button type="button" onClick={copy} className="underline hover:text-[var(--chan-ink)]">
          {copied ? (tx("Skopiowano", "Copied")) : (tx("Kopiuj", "Copy"))}
        </button>
        <button type="button" onClick={download} className="underline hover:text-[var(--chan-ink)]">
          {tx("Pobierz", "Download")}
        </button>
      </div>
    </div>
  );
}

export function TwoFactorPart({ tx, hasPassword }: { tx: Tx; hasPassword: boolean }) {
  const user = useAccountUser();
  // One password field per action (audit AUTH-13): typing the password to get new backup codes and
  // pressing Enter must never turn two-step verification off.
  const [enablePassword, setEnablePassword] = useState("");
  const [codesPassword, setCodesPassword] = useState("");
  const [disablePassword, setDisablePassword] = useState("");
  const [setup, setSetup] = useState<{ uri: string; backupCodes: string[] } | null>(null);
  const [code, setCode] = useState("");
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState<Msg>(EMPTY);
  const [newCodes, setNewCodes] = useState<string[] | null>(null);

  if (!hasPassword) {
    return (
      <p className="text-[13px] text-[var(--chan-muted)]">
        {tx("Weryfikacja dwuetapowa dotyczy logowania hasłem. Ustaw hasło powyżej (link przyjdzie na e-mail), a potem będziesz mógł ją włączyć. Logowanie przez Google korzysta z zabezpieczeń Twojego konta Google.", "Two-step verification protects password sign-in. Set a password above (a link is sent to your email), then you can turn it on. Signing in with Google uses your Google account's own protection.")}
      </p>
    );
  }

  function start(e: React.FormEvent) {
    e.preventDefault();
    return guarded(setLoading, setMsg, tx, async () => {
      const { data, error } = await authClient.twoFactor.enable({ password: enablePassword });
      if (error || !data || !("totpURI" in data)) return setMsg({ error: authErrorMessage(error, tx), info: null });
      setSetup({ uri: data.totpURI, backupCodes: data.backupCodes });
      setEnablePassword("");
    });
  }

  function confirm(e: React.FormEvent) {
    e.preventDefault();
    return guarded(setLoading, setMsg, tx, async () => {
      const { error } = await authClient.twoFactor.verifyTotp({ code: code.trim() });
      if (error) return setMsg({ error: authErrorMessage(error, tx), info: null });
      setSetup(null);
      setCode("");
      await refreshSession();
      setMsg({ error: null, info: tx("Weryfikacja dwuetapowa włączona.", "Two-step verification is on.") });
    });
  }

  function regenerateCodes(e: React.FormEvent) {
    e.preventDefault();
    return guarded(setLoading, setMsg, tx, async () => {
      const { data, error } = await authClient.twoFactor.generateBackupCodes({ password: codesPassword });
      if (error || !data) return setMsg({ error: authErrorMessage(error, tx), info: null });
      setCodesPassword("");
      setNewCodes(data.backupCodes);
      setMsg({ error: null, info: tx("Wygenerowano nowe kody. Poprzednie przestały działać.", "New codes generated. The old ones no longer work.") });
    });
  }

  function disable(e: React.FormEvent) {
    e.preventDefault();
    return guarded(setLoading, setMsg, tx, async () => {
      const { error } = await authClient.twoFactor.disable({ password: disablePassword });
      if (error) return setMsg({ error: authErrorMessage(error, tx), info: null });
      setDisablePassword("");
      setNewCodes(null);
      await refreshSession();
      setMsg({ error: null, info: tx("Weryfikacja dwuetapowa wyłączona.", "Two-step verification is off.") });
    });
  }

  if (setup) {
    return (
      <form onSubmit={confirm} className="space-y-3">
        <Feedback error={msg.error} info={msg.info} />
        <p className="text-[13px] text-[var(--chan-body)]">
          {tx("Zeskanuj kod w aplikacji uwierzytelniającej, a potem wpisz 6-cyfrowy kod.", "Scan the code in an authenticator app, then enter the 6-digit code.")}
        </p>
        <div className="flex justify-center rounded-lg bg-white p-3"><QRCodeSVG value={setup.uri} size={160} /></div>
        <BackupCodesBox codes={setup.backupCodes} tx={tx} />
        <Field label={tx("Kod z aplikacji", "Code from the app")} value={code} onChange={setCode} inputMode="numeric" autoComplete="one-time-code" />
        <Primary loading={loading} label={tx("Włącz", "Turn on")} />
      </form>
    );
  }

  const status = (
    <p className="text-[13px] font-bold text-[var(--chan-ink)]">
      {tx("Weryfikacja dwuetapowa (TOTP)", "Two-step verification (TOTP)")}: {user.twoFactorEnabled ? (tx("włączona", "on")) : (tx("wyłączona", "off"))}
    </p>
  );

  if (!user.twoFactorEnabled) {
    return (
      <form onSubmit={start} className="space-y-3 border-t border-[var(--chan-line)] pt-3">
        <Feedback error={msg.error} info={msg.info} />
        {status}
        <Field label={tx("Hasło", "Password")} type="password" value={enablePassword} onChange={setEnablePassword} autoComplete="current-password" />
        <Primary loading={loading} label={tx("Włącz", "Turn on")} />
      </form>
    );
  }

  return (
    <div className="space-y-3 border-t border-[var(--chan-line)] pt-3">
      <Feedback error={msg.error} info={msg.info} />
      {status}
      <form onSubmit={regenerateCodes} aria-label={tx("Nowe kody zapasowe", "New backup codes")} className="space-y-2">
        {newCodes && <BackupCodesBox codes={newCodes} tx={tx} />}
        <Field label={tx("Hasło do nowych kodów zapasowych", "Password for new backup codes")} type="password" value={codesPassword} onChange={setCodesPassword} autoComplete="current-password" />
        <Primary loading={loading} label={tx("Wygeneruj nowe kody zapasowe", "Generate new backup codes")} />
      </form>
      <form onSubmit={disable} aria-label={tx("Wyłącz weryfikację dwuetapową", "Turn off two-step verification")} className="space-y-2 border-t border-[var(--chan-line)] pt-3">
        <Field label={tx("Hasło do wyłączenia weryfikacji", "Password to turn verification off")} type="password" value={disablePassword} onChange={setDisablePassword} autoComplete="current-password" />
        <button
          type="submit"
          disabled={loading || !disablePassword}
          className="flex h-[44px] w-full items-center justify-center rounded-[12px] border border-red-600 font-brand text-[15px] font-bold text-red-600 transition-colors hover:bg-red-50 disabled:opacity-50"
        >
          {tx("Wyłącz weryfikację dwuetapową", "Turn off two-step verification")}
        </button>
      </form>
    </div>
  );
}

type DeviceSession = { id: string; token: string; userAgent?: string | null; ipAddress?: string | null; updatedAt: Date | string };

function SessionsPart({ tx }: { tx: Tx }) {
  const [sessions, setSessions] = useState<DeviceSession[] | null>(null);
  const [currentToken, setCurrentToken] = useState<string | null>(null);
  const [msg, setMsg] = useState<Msg>(EMPTY);
  const [needsReauth, setNeedsReauth] = useState(false);

  // Better Auth only lists/revokes devices for a session younger than `freshAge`; an older one gets
  // SESSION_NOT_FRESH and must sign in again (never a silently empty list).
  function report(error: { code?: string; message?: string; status?: number }) {
    if (isSessionNotFresh(error)) return setNeedsReauth(true);
    setMsg({ error: authErrorMessage(error, tx), info: null });
  }

  async function load() {
    try {
      const [list, current] = await Promise.all([authClient.listSessions(), authClient.getSession()]);
      if (list.error) {
        setSessions([]);
        return report(list.error);
      }
      setNeedsReauth(false);
      setSessions((list.data as DeviceSession[] | null) ?? []);
      setCurrentToken(current.data?.session?.token ?? null);
    } catch {
      setSessions([]);
      report(NETWORK_ERROR);
    }
  }

  useEffect(() => {
    void load();
  }, []);

  async function revoke(token: string) {
    try {
      const { error } = await authClient.revokeSession({ token });
      if (error) return report(error);
      await load();
    } catch {
      report(NETWORK_ERROR);
    }
  }

  async function revokeOthers() {
    try {
      const { error } = await authClient.revokeOtherSessions();
      if (error) return report(error);
      setMsg({ error: null, info: tx("Wylogowano pozostałe urządzenia.", "Other devices were signed out.") });
      await load();
    } catch {
      report(NETWORK_ERROR);
    }
  }

  return (
    <div className="space-y-2 border-t border-[var(--chan-line)] pt-3">
      <Feedback error={msg.error} info={msg.info} />
      {needsReauth && <ReauthNotice tx={tx} />}
      <p className="text-[13px] font-bold text-[var(--chan-ink)]">{tx("Zalogowane urządzenia", "Signed-in devices")}</p>
      <ul className="space-y-2">
        {(sessions ?? []).map((s) => (
          <li key={s.id} className="flex items-center justify-between gap-2 rounded-lg border border-[var(--chan-line)] px-3 py-2">
            <div className="min-w-0">
              <p className="truncate text-[13px] font-semibold">{(s.userAgent || (tx("Nieznane urządzenie", "Unknown device"))).slice(0, 60)}</p>
              <p className="text-[11px] text-[var(--chan-muted)]">
                {s.token === currentToken ? (tx("To urządzenie", "This device")) : new Date(s.updatedAt).toLocaleString(intlLocale(tx.language, "en-GB"))}
              </p>
            </div>
            {s.token !== currentToken && (
              <button type="button" onClick={() => revoke(s.token)} className="shrink-0 text-[12px] font-bold text-red-600 hover:underline">
                {tx("Wyloguj", "Sign out")}
              </button>
            )}
          </li>
        ))}
      </ul>
      {sessions && sessions.length > 1 && (
        <button type="button" onClick={revokeOthers} className="text-[12px] font-bold underline hover:text-[var(--chan-ink)]">
          {tx("Wyloguj pozostałe urządzenia", "Sign out other devices")}
        </button>
      )}
    </div>
  );
}

export function SecuritySection({ tx }: { tx: Tx }) {
  const { hasPassword, failed, retry } = useHasPassword();

  if (failed) {
    return (
      <div role="alert" className="space-y-2 rounded-lg bg-red-50 px-3 py-2">
        <p className="text-[13px] font-semibold text-red-600">{authErrorMessage(NETWORK_ERROR, tx)}</p>
        <button type="button" onClick={retry} className="text-[12px] font-bold text-red-700 underline">
          {tx("Spróbuj ponownie", "Try again")}
        </button>
      </div>
    );
  }
  if (hasPassword === null) return null;
  return (
    <div className="space-y-4">
      <PasswordPart tx={tx} hasPassword={hasPassword} />
      <TwoFactorPart tx={tx} hasPassword={hasPassword} />
      <SessionsPart tx={tx} />
    </div>
  );
}

"use client";

import { Suspense, useCallback, useEffect, useId, useRef, useState } from "react";
import Image from "next/image";
import Link from "next/link";
import { BookOpen, Home, LayoutDashboard, LogOut, Settings, ShieldCheck, Users } from "lucide-react";
import { useAuth, useUser } from "@/lib/auth/react";
import { ADMIN_PANEL_ORIGIN } from "@/lib/admin-legacy-redirects";
import { getLocalizedHref } from "@/lib/i18n/routing";
import { useLanguage } from "../LanguageContext";
import { CloseButton } from "@/components/ui/close-button";
import AccountModal from "./AccountModal";
import LanguageSwitcher from "../LanguageSwitcher";
import { useSwitchLanguage } from "../useSwitchLanguage";

interface UserMenuProps {
  isAdmin: boolean;
}

/** The language button of the account panel; useSwitchLanguage reads the URL, so it sits in its own Suspense. */
function PanelLanguage() {
  const { language } = useLanguage();
  const switchLanguage = useSwitchLanguage();
  return <LanguageSwitcher language={language} onSelect={switchLanguage} variant="dropdown" />;
}

type SubscribedChannel = { id: string; slug: string; handle: string | null; name: string };

/** How many followed channels the panel lists; the rest is one click away on the subscriptions page. */
const PANEL_CHANNEL_LIMIT = 8;
/** Length of the slide-out (matches duration-200 on the panel and its backdrop). */
const PANEL_EXIT_MS = 200;
/** Studio access per account for the lifetime of the page session, so navigating does not ask again. */
const studioAccessCache = new Map<string, boolean>();

/**
 * Account panel. The avatar in the top bar opens a side panel from the right: who is signed in, the main places of
 * the site (home, Studio, account, the administrator panel), the channels the viewer follows, the legal documents and
 * the sign-out button pinned at the bottom. It replaces both the old dropdown and the left "hamburger" menu, which
 * duplicated each other. A modal dialog on every screen size: focus moves in, Esc and the backdrop close it, focus
 * returns to the avatar. Better Auth is the identity backend; the application owns all visible account UI.
 */
export default function UserMenu({ isAdmin }: UserMenuProps) {
  const { user } = useUser();
  const { signOut } = useAuth();
  const { language, tx } = useLanguage();
  const [open, setOpen] = useState(false);
  // The panel slides out before it unmounts: `closing` plays the exit animation, then `open` goes false.
  const [closing, setClosing] = useState(false);
  const [accountOpen, setAccountOpen] = useState(false);
  const [accountSection, setAccountSection] = useState<"profile" | "notifications">("profile");
  const [channels, setChannels] = useState<SubscribedChannel[] | null>(null);
  const [failed, setFailed] = useState(false);
  // Studio is only offered to accounts that have a channel or may create one (the creation gate is closed for most).
  const [studioAccessState, setStudioAccessState] = useState<{ userId: string; value: boolean } | null>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  const panelId = useId();

  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const dismiss = useCallback(() => {
    if (closeTimer.current) return;
    setClosing(true);
    closeTimer.current = setTimeout(() => {
      closeTimer.current = null;
      setOpen(false);
      setClosing(false);
    }, PANEL_EXIT_MS);
  }, []);

  const close = useCallback(() => {
    dismiss();
    triggerRef.current?.focus();
  }, [dismiss]);

  const openAccount = useCallback((section: "profile" | "notifications") => {
    if (closeTimer.current) clearTimeout(closeTimer.current);
    closeTimer.current = null;
    setOpen(false);
    setClosing(false);
    setAccountSection(section);
    setAccountOpen(true);
  }, []);

  useEffect(() => {
    const openSettings = () => openAccount("notifications");
    window.addEventListener("polutek:open-notification-settings", openSettings);
    return () => window.removeEventListener("polutek:open-notification-settings", openSettings);
  }, [openAccount]);

  useEffect(
    () => () => {
      if (closeTimer.current) clearTimeout(closeTimer.current);
    },
    [],
  );

  useEffect(() => {
    if (!open) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") close();
    };
    document.addEventListener("keydown", onKey);
    // The page behind must not scroll: lock the ROOT only (the viewport is the scroller). An inline overflow on the body must NOT
    // be set: with `html` already non-visible it stops propagating to the viewport and makes the body a scroll
    // container of its own, so the sticky top bar loses its viewport anchor and rises by `scrollY` (and the page can
    // scroll sideways when the focus moves into the sliding panel). `html` has `scrollbar-gutter: stable`
    // (globals.css), so the scrollbar's space normally stays reserved while it is hidden and the layout does not move.
    // Padding the body as well would shift the page by the scrollbar's width a second time, so it is added only when
    // the MEASURED width of the page actually grew (a browser that does not keep the gutter), by exactly that growth.
    const root = document.documentElement;
    const body = document.body;
    const previous = { rootOverflow: root.style.overflow, bodyPaddingRight: body.style.paddingRight };
    const widthBefore = body.getBoundingClientRect().width;
    root.style.overflow = "hidden";
    const grew = body.getBoundingClientRect().width - widthBefore;
    if (grew > 0.5) body.style.paddingRight = `${grew}px`;
    // preventScroll: the panel is still translated off-screen while it slides in; never scroll anything to reach it.
    closeRef.current?.focus({ preventScroll: true });
    return () => {
      document.removeEventListener("keydown", onKey);
      root.style.overflow = previous.rootOverflow;
      body.style.paddingRight = previous.bodyPaddingRight;
    };
  }, [open, close]);

  // The followed channels are read when the panel opens (own data, never cached).
  const userId = user?.id;
  useEffect(() => {
    if (!open || !userId) return;
    const controller = new AbortController();
    setFailed(false);
    fetch("/api/user/subscribed-channels", { cache: "no-store", signal: controller.signal })
      .then((response) => (response.ok ? (response.json() as Promise<{ items: SubscribedChannel[] }>) : Promise.reject(new Error("status"))))
      .then((data) => setChannels(data.items))
      .catch(() => {
        if (!controller.signal.aborted) setFailed(true);
      });
    return () => controller.abort();
  }, [open, userId]);

  // Read as soon as the avatar is on screen, so the answer is there before the panel is opened: the link is never
  // shown "for a moment" and then removed, and it appears only once the account is known to be allowed.
  useEffect(() => {
    if (!userId || studioAccessCache.has(userId)) return;
    const controller = new AbortController();
    fetch("/api/studio/me", { cache: "no-store", signal: controller.signal })
      .then((response) => (response.ok ? (response.json() as Promise<{ channels?: unknown[]; canCreateChannel?: boolean }>) : Promise.reject(new Error("status"))))
      .then((data) => {
        const value = (data.channels?.length ?? 0) > 0 || data.canCreateChannel === true;
        studioAccessCache.set(userId, value);
        setStudioAccessState({ userId, value });
      })
      .catch(() => {
        // Unknown: keep the link hidden for now and ask again on the next mount.
      });
    return () => controller.abort();
  }, [userId]);
  const studioAccess = userId ? (studioAccessCache.get(userId) ?? (studioAccessState?.userId === userId ? studioAccessState.value : false)) : false;

  if (!user) return null;

  const displayName = user.fullName || user.primaryEmailAddress?.emailAddress || "";
  const email = user.primaryEmailAddress?.emailAddress || "";
  const avatar = user.imageUrl;
  const initial = (displayName[0] || "?").toUpperCase();

  const itemClass =
    "flex min-h-11 w-full items-center gap-3 rounded-xl px-3 text-left text-[14px] font-semibold text-[var(--chan-ink)] transition-colors hover:bg-[var(--chan-surface)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--chan-blue)]";
  const iconClass = "h-5 w-5 shrink-0";
  const sectionTitleClass = "px-3 text-[12px] font-bold uppercase tracking-[0.14em] text-[var(--chan-muted)]";

  const avatarImage = (size: number) =>
    avatar ? (
      <Image src={avatar} alt="" width={size} height={size} className="h-full w-full object-cover" unoptimized />
    ) : (
      <span className="text-[13px] font-bold text-[var(--chan-ink)]">{initial}</span>
    );

  const visibleChannels = channels?.slice(0, PANEL_CHANNEL_LIMIT) ?? [];

  return (
    <>
      <button
        ref={triggerRef}
        type="button"
        onClick={() => setOpen(true)}
        aria-label={tx("Menu konta", "Account menu")}
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-controls={panelId}
        className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full transition-[transform,background-color,box-shadow] duration-160 hover:-translate-y-px hover:bg-[var(--chan-surface)] hover:shadow-[0_4px_12px_rgba(23,23,23,0.08)] active:scale-95 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--chan-blue)] motion-reduce:transform-none motion-reduce:transition-none"
      >
        <span className="flex h-9 w-9 items-center justify-center overflow-hidden rounded-full border border-[var(--chan-line)]">
          {avatarImage(36)}
        </span>
      </button>

      {open ? (
        <div className="fixed inset-0 z-[1100]">
          <button
            type="button"
            tabIndex={-1}
            aria-hidden="true"
            onClick={close}
            className={`absolute inset-0 h-full w-full cursor-default touch-none bg-black/40 duration-200 ${closing ? "animate-out fade-out fill-mode-forwards" : "animate-in fade-in"}`}
          />
          <aside
            id={panelId}
            role="dialog"
            aria-modal="true"
            aria-label={tx("Menu konta", "Account menu")}
            className={`absolute right-0 top-0 flex h-full w-[min(88vw,320px)] flex-col overscroll-contain bg-[var(--chan-card)] shadow-2xl duration-200 ${closing ? "animate-out slide-out-to-right fill-mode-forwards" : "animate-in slide-in-from-right"}`}
          >
            <div className="border-b border-[var(--chan-line)]">
            <div className="flex items-start gap-3 p-4 pb-2 pr-14">
              <span className="flex h-12 w-12 shrink-0 items-center justify-center overflow-hidden rounded-full border border-[var(--chan-line)]">
                {avatarImage(48)}
              </span>
              <div className="min-w-0 flex-1 pt-0.5">
                <p className="truncate text-[15px] font-bold text-[var(--chan-ink)]">{displayName}</p>
                {email && email !== displayName ? <p className="truncate text-[12px] text-[var(--chan-muted)]">{email}</p> : null}
              </div>
              <CloseButton ref={closeRef} onClick={close} aria-label={tx("Zamknij menu", "Close menu")} />
            </div>
            <div className="flex justify-end px-4 pb-3">
              <Suspense fallback={null}>
                <PanelLanguage />
              </Suspense>
            </div>
            </div>

            <div className="flex flex-1 flex-col overflow-y-auto overscroll-contain p-3">
              <nav aria-label={tx("Nawigacja boczna", "Side navigation")} className="grid gap-1">
                <Link href={getLocalizedHref(language, "home")} className={itemClass} onClick={dismiss}>
                  <Home className={iconClass} strokeWidth={1.8} aria-hidden="true" />
                  {tx("Strona główna", "Home")}
                </Link>
                {studioAccess ? (
                  <Link href={getLocalizedHref(language, "studio")} className={itemClass} onClick={dismiss}>
                    <LayoutDashboard className={iconClass} strokeWidth={1.8} aria-hidden="true" />
                    {tx("Studio twórcy", "Creator Studio")}
                  </Link>
                ) : null}
                <button
                  type="button"
                  className={itemClass}
                  onClick={() => openAccount("profile")}
                >
                  <Settings className={iconClass} strokeWidth={1.8} aria-hidden="true" />
                  {tx("Moje konto", "My account")}
                </button>
                {isAdmin ? (
                  <a href={ADMIN_PANEL_ORIGIN} target="_blank" rel="noopener noreferrer" className={itemClass}>
                    <ShieldCheck className={iconClass} strokeWidth={1.8} aria-hidden="true" />
                    {tx("Panel admina", "Admin panel")}
                  </a>
                ) : null}
              </nav>

              <section aria-labelledby={`${panelId}-subs`} className="mb-4 mt-4 grid gap-1 border-t border-[var(--chan-line)] pt-3">
                <h2 id={`${panelId}-subs`} className={sectionTitleClass}>
                  {tx("Subskrypcje", "Subscriptions")}
                </h2>
                <Link href={getLocalizedHref(language, "subscriptions")} className={itemClass} onClick={dismiss}>
                  <Users className={iconClass} strokeWidth={1.8} aria-hidden="true" />
                  {tx("Wszystkie subskrypcje", "All subscriptions")}
                </Link>
                {failed ? (
                  <p className="px-3 text-[13px] text-[var(--chan-muted)]" role="alert">
                    {tx("Nie udało się wczytać subskrypcji.", "Could not load your subscriptions.")}
                  </p>
                ) : channels === null ? (
                  <p className="px-3 text-[13px] text-[var(--chan-muted)]">{tx("Wczytuję…", "Loading…")}</p>
                ) : channels.length === 0 ? (
                  <p className="px-3 text-[13px] text-[var(--chan-muted)]">{tx("Nie subskrybujesz jeszcze żadnego kanału.", "You do not follow any channel yet.")}</p>
                ) : (
                  <ul className="grid gap-1">
                    {visibleChannels.map((channel) => (
                      <li key={channel.id}>
                        <Link href={getLocalizedHref(language, "channel", { slug: channel.slug })} className={itemClass} onClick={dismiss}>
                          <span className="min-w-0 truncate pl-8">{channel.name}</span>
                        </Link>
                      </li>
                    ))}
                  </ul>
                )}
              </section>

              <nav aria-label={tx("Informacje prawne", "Legal")} className="mt-auto grid gap-1 border-t border-[var(--chan-line)] pt-3">
                <Link href={getLocalizedHref(language, "terms")} className={itemClass} onClick={dismiss}>
                  <BookOpen className={iconClass} strokeWidth={1.8} aria-hidden="true" />
                  {tx("Regulamin", "Terms")}
                </Link>
                <Link href={getLocalizedHref(language, "privacy")} className={itemClass} onClick={dismiss}>
                  <ShieldCheck className={iconClass} strokeWidth={1.8} aria-hidden="true" />
                  {tx("Polityka prywatności", "Privacy policy")}
                </Link>
              </nav>
            </div>

            <div className="border-t border-[var(--chan-line)] p-3">
              <button
                type="button"
                onClick={() => void signOut()}
                className="flex min-h-11 w-full items-center gap-3 rounded-xl px-3 text-left text-[14px] font-semibold text-red-700 transition-colors hover:bg-red-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-400"
              >
                <LogOut className={iconClass} strokeWidth={1.8} aria-hidden="true" />
                {tx("Wyloguj się", "Sign out")}
              </button>
            </div>
          </aside>
        </div>
      ) : null}

      <AccountModal open={accountOpen} onOpenChange={setAccountOpen} isAdmin={isAdmin} initialSection={accountSection} />
    </>
  );
}

"use client";
// Hidden since 2026-10-21, kept on purpose: nothing opens this modal (app/components/channel/tip-gate.ts). Several
// app/components/support/* parts (TipPayStep, TipPayFrame, TipSelect, ...) are shared with the patron checkout and live.

import React, { useCallback, useEffect, useMemo, useState } from "react";
import { Elements } from "@stripe/react-stripe-js";
import type { StripeElementsOptions } from "@stripe/stripe-js";
import { CloseButton } from "@/components/ui/close-button";
import { Dialog, DialogOverlay, DialogPopup, DialogPortal, DialogTitle } from "@/components/ui/dialog";
import { useLanguage } from "../LanguageContext";
import { useAuthModal } from "../auth/AuthModalProvider";
import { cn } from "@/lib/utils";
import { APP_NAME, type SupportedCurrency } from "@/lib/constants";
import { getStripeBrowser } from "@/lib/payments/stripe-browser";
import { detectDefaultCurrency } from "@/lib/payments/detect-currency";
import { useCheckoutFlow } from "@/lib/hooks/useCheckoutFlow";
import {
  TIP_WALLETS,
  getTipMethodTiles,
  readLastTipMethod,
  rememberTipMethod,
  type TipStep,
  type TipWallet,
} from "../support/tip-flow-config";
import { TipRecipientStep } from "../support/TipRecipientStep";
import { TipDisclaimerStep } from "../support/TipDisclaimerStep";
import { TipAmountStep } from "../support/TipAmountStep";
import { TipMethodStep } from "../support/TipMethodStep";
import { TipPayStep } from "../support/TipPayStep";
import { TipThanksStep } from "../support/TipThanksStep";
import { TipBackContext } from "../support/TipStepLayout";
import { stripeLocale } from "@/lib/i18n/ui";

interface SupportModalProps {
  onClose: () => void;
}

const STEPS: TipStep[] = ["recipient", "disclaimer", "amount", "method", "pay"];

/**
 * The tip gate, opened from "Wspieraj" (ChannelHome). Five steps: recipient + Terms/Privacy
 * consent → disclaimer ("a tip unlocks nothing") → amount → method → that method's form, then the
 * thank-you screen. A fixed-size window on desktop, full screen on phones; the frame (badge, dots,
 * back, ✕, footer button) never changes size between steps.
 *
 * Stripe decides which methods a tip can use: the intent is created with automatic payment
 * methods when the amount step is confirmed (and updated, not duplicated, if the amount changes)
 * and its `payment_method_types` become the tiles (plus Apple Pay / Google Pay when the device has
 * one); the chosen one is confirmed with its own Stripe.js call on the same intent. Success
 * reconciles through /api/payments/[id] → fulfillPayment(). Mounted only while open, which is
 * also when Stripe.js is first downloaded.
 */
export default function SupportModal({ onClose }: SupportModalProps) {
  const { language, tx } = useLanguage();
  const { open: openAuthModal } = useAuthModal();

  const flow = useCheckoutFlow({ tx });
  // Stripe.js is requested here, i.e. only once somebody opens the gate.
  const stripePromise = useMemo(() => getStripeBrowser(), []);

  // Controls the Base UI dialog open state. Starts true (component only mounts when open).
  // On close we set false first so Base UI can apply data-closed and play the slide-up
  // animation before the parent unmounts the component.
  const [localOpen, setLocalOpen] = useState(true);

  const [currency, setCurrency] = useState<SupportedCurrency>(() => detectDefaultCurrency(language));
  const [amount, setAmount] = useState<number | "">("");
  const [termsAccepted, setTermsAccepted] = useState(false);
  const [step, setStep] = useState<TipStep>("recipient");
  const [pickedMethod, setPickedMethod] = useState<string | null>(() => readLastTipMethod());
  const [creatingIntent, setCreatingIntent] = useState(false);
  const [wallets, setWallets] = useState<TipWallet[]>([]);

  // Apple Pay / Google Pay get a tile only when this browser has one set up.
  useEffect(() => {
    let active = true;
    stripePromise
      .then((stripe) =>
        stripe
          ?.paymentRequest({
            country: "PL",
            currency: currency.toLowerCase(),
            total: { label: APP_NAME, amount: 100 },
            disableWallets: ["link", "browserCard"],
          })
          .canMakePayment(),
      )
      .then((result) => {
        if (active) setWallets(TIP_WALLETS.filter((wallet) => (wallet === "apple_pay" ? result?.applePay : result?.googlePay)));
      })
      .catch(() => undefined);
    return () => {
      active = false;
    };
  }, [currency, stripePromise]);

  const minAmount = flow.minimums[currency];
  const methods = getTipMethodTiles(flow.paymentMethodTypes, wallets);
  // The viewer's pick (or last-used method) when Stripe allows it for this tip, else the first tile.
  const method = pickedMethod && methods.includes(pickedMethod) ? pickedMethod : methods[0] ?? null;

  const handleAmountNext = async () => {
    if (!flow.userId) {
      openAuthModal("sign-in");
      return;
    }
    if (amount === "") return;
    setCreatingIntent(true);
    const ready = await flow.submit(amount, currency, minAmount, termsAccepted);
    setCreatingIntent(false);
    if (ready) setStep("method");
  };

  // The intent stays: going on with a new amount updates it on the server.
  const backToAmount = () => {
    flow.resetCheckout();
    setStep("amount");
  };

  const goBack = () => {
    if (step === "pay") setStep("method");
    else if (step === "method") backToAmount();
    else if (step === "amount") setStep("disclaimer");
    else if (step === "disclaimer") setStep("recipient");
  };

  const handleClose = useCallback(() => {
    if (flow.isSuccess) flow.closeSuccessAndSync();
    setLocalOpen(false);
    onClose();
  }, [flow, onClose]);

  const handleTryAgain = useCallback(() => {
    flow.closeSuccessAndSync();
    backToAmount();
  }, [flow]);

  const handleConfirmed = (outcome: "succeeded" | "processing") => {
    if (flow.paymentId) flow.trackConfirmedPayment(flow.paymentId, outcome);
  };

  const elementsOptions: StripeElementsOptions | null = flow.clientSecret
    ? {
        clientSecret: flow.clientSecret,
        locale: stripeLocale(language),
        appearance: {
          theme: "flat",
          variables: {
            colorPrimary: "#2563eb",
            colorBackground: "#ffffff",
            colorText: "#1a1a1a",
            borderRadius: "12px",
            fontFamily: "var(--font-geist-sans)",
          },
        },
      }
    : null;

  const showThanks = flow.isSuccess;
  const activeIndex = showThanks ? STEPS.length : STEPS.indexOf(step);
  const canGoBack = !showThanks && step !== "recipient";

  let body: React.ReactNode;
  if (showThanks) {
    body = (
      <TipThanksStep
        language={language}
        paymentUiStatus={flow.paymentUiStatus}
        isSyncing={flow.isSyncing}
        onRetryStatusCheck={flow.handleRetryStatusCheck}
        onTryAgain={handleTryAgain}
        onDone={handleClose}
      />
    );
  } else if (step !== "amount" && elementsOptions && amount !== "") {
    body = (
      // One Elements group per intent; the per-method forms confirm against its client secret.
      // Keyed by amount/currency too: the intent is updated in place, and the wallet and Payment
      // Element forms must re-read it after a change.
      <Elements key={`${flow.clientSecret}:${amount}:${currency}`} stripe={stripePromise} options={elementsOptions}>
        {step === "method" || !method ? (
          <TipMethodStep
            language={language}
            amount={amount}
            currency={currency}
            methods={methods}
            selected={method}
            onSelect={setPickedMethod}
            onNext={() => {
              if (!method) return;
              rememberTipMethod(method);
              setStep("pay");
            }}
            onChangeAmount={backToAmount}
          />
        ) : (
          <TipPayStep
            language={language}
            amount={amount}
            currency={currency}
            method={method}
            clientSecret={flow.clientSecret!}
            paymentId={flow.paymentId}
            userEmail={flow.userEmail}
            stripePromise={stripePromise}
            onChangeMethod={() => setStep("method")}
            onConfirmed={handleConfirmed}
          />
        )}
      </Elements>
    );
  } else if (step === "recipient") {
    body = (
      <TipRecipientStep
        language={language}
        termsAccepted={termsAccepted}
        onTermsChange={setTermsAccepted}
        onNext={() => setStep("disclaimer")}
        onClose={handleClose}
      />
    );
  } else if (step === "disclaimer") {
    body = (
      <TipDisclaimerStep
        language={language}
        onNext={() => setStep("amount")}
        onClose={handleClose}
      />
    );
  } else {
    body = (
      <TipAmountStep
        language={language}
        currency={currency}
        onCurrencyChange={setCurrency}
        amount={amount}
        onAmountChange={setAmount}
        minAmount={minAmount}
        onNext={() => void handleAmountNext()}
        busy={creatingIntent || flow.isInitialLoading}
      />
    );
  }

  return (
    // `disablePointerDismissal`: Stripe's 3DS/wallet/BLIK overlays are appended to <body> and
    // must never count as outside presses that close the gate mid-payment.
    <Dialog open={localOpen} onOpenChange={(open) => { if (!open) handleClose(); }} disablePointerDismissal>
      <DialogPortal>
        <DialogOverlay className="tip-gate-overlay z-[9990] bg-black/40 supports-backdrop-filter:backdrop-blur-sm" />
        <DialogPopup
          data-testid="support-modal"
          className="fixed inset-0 z-[9991] flex h-[100dvh] w-screen tip-gate-surface flex-col overflow-hidden outline-none md:inset-auto md:left-1/2 md:top-1/2 md:h-[min(640px,90dvh)] md:w-[440px] md:-translate-x-1/2 md:-translate-y-1/2 md:rounded-[24px] md:border md:border-[var(--chan-line)] md:shadow-[0_30px_80px_-30px_rgba(17,24,39,0.14)]"
        >
          <DialogTitle className="sr-only">{tx("Bramka napiwkowa", "Tip gate")}</DialogTitle>

          <header className="flex pr-14 shrink-0 items-center gap-2 px-5 pb-2 pt-[max(12px,env(safe-area-inset-top))] md:px-7 md:pr-14 md:pt-4">
            <span className="inline-flex shrink-0 items-center rounded-full bg-[var(--chan-ink)] px-3 py-1 text-[11px] font-extrabold uppercase tracking-[0.12em] text-white">
              {tx("Bramka napiwkowa", "Tip gate")}
            </span>
            <div className="ml-auto flex items-center gap-1.5" aria-hidden="true">
              {STEPS.map((key, index) => (
                <span
                  key={key}
                  className={cn(
                    "h-1.5 rounded-full transition-[width,background-color] duration-300 motion-reduce:transition-none",
                    index === activeIndex ? "w-6 bg-[var(--chan-ink)]" : "w-1.5",
                    index < activeIndex ? "bg-[var(--chan-ink)]" : index > activeIndex && "bg-[var(--chan-line)]",
                  )}
                />
              ))}
            </div>
            <CloseButton onClick={handleClose} aria-label={tx("Zamknij", "Close")} />
          </header>

          <div
            key={showThanks ? "thanks" : step}
            className="flex min-h-0 flex-1 flex-col"
          >
            <TipBackContext.Provider value={canGoBack ? { onBack: goBack, label: tx("Wstecz", "Back") } : null}>
              {body}
            </TipBackContext.Provider>
          </div>
        </DialogPopup>
      </DialogPortal>
    </Dialog>
  );
}

