"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useAuth, useUser } from "@/lib/auth/react";
import { useAuthModal } from "@/app/components/auth/AuthModalProvider";
import { useSearchParams } from "next/navigation";
import { useQueryClient } from "@tanstack/react-query";
import { logger } from "@/lib/logger";
import { MIN_PAYMENT_BY_CURRENCY, SUPPORTED_CURRENCIES, type SupportedCurrency } from "@/lib/constants";
import { useToast } from "@/app/hooks/useToast";
import { LEGAL_DOCUMENTS_VERSION } from "@/lib/legal/version";
import type { Tx } from "@/lib/i18n/ui";

// Query params Stripe/our return URL add after a redirect-based payment method.
const STRIPE_RETURN_PARAMS = [
  "payment_intent",
  "payment_intent_client_secret",
  "redirect_status",
  "payment_id",
  "success",
];

/**
 * One tip attempt = one requestId = one PaymentIntent on the server (which updates the intent when
 * the amount changes). Kept for the tab's session, so closing and re-opening the gate continues
 * the same attempt instead of opening a new intent; dropped once the attempt is finished.
 */
const ATTEMPT_STORAGE_KEY = "pp:tip-attempt-id";

function readAttemptId(): string | null {
  try {
    return window.sessionStorage.getItem(ATTEMPT_STORAGE_KEY);
  } catch {
    return null;
  }
}

function storeAttemptId(id: string | null) {
  try {
    if (id) window.sessionStorage.setItem(ATTEMPT_STORAGE_KEY, id);
    else window.sessionStorage.removeItem(ATTEMPT_STORAGE_KEY);
  } catch {
    // Storage blocked (private mode): the attempt simply lives as long as this hook.
  }
}

/** Payment status as reported by GET /api/payments/[id] (PaymentUiStatus) plus local states. */
export type TipUiStatus = "PROCESSING" | "SUCCEEDED" | "FAILED" | "REFUNDED" | "TIMED_OUT";

export interface UseCheckoutFlowOptions {
  /** True for Polish copy, false for English — drives the handful of fixed toast strings. */
  tx: Tx;
}

export interface UseCheckoutFlowResult {
  /** Signed-in viewer id, or null/undefined when signed out. */
  userId: string | null | undefined;
  /** Viewer's e-mail, prefilled where a payment form asks for one. */
  userEmail: string | undefined;

  isInitialLoading: boolean;
  /** Minimum tip per currency (major units), the same one the server enforces. */
  minimums: Record<SupportedCurrency, number>;

  clientSecret: string | null;
  /** Methods Stripe allows for the current intent (from create-intent); drives the tip gate tiles. */
  paymentMethodTypes: string[];
  paymentId: string | null;
  paymentUiStatus: TipUiStatus | null;
  /** True once a confirmed payment (or a Stripe return) moved the gate to its result screen. */
  isSuccess: boolean;
  isSyncing: boolean;

  /** Re-checks payment status on demand (the "check again" action). */
  handleRetryStatusCheck: () => Promise<void>;
  /** Leaves the result screen: full reload after a confirmed payment, URL cleanup otherwise. */
  closeSuccessAndSync: () => void;
  /**
   * Creates or updates the intent for this amount; resolves true once a client secret is ready.
   * `termsAccepted`: the payer ticked the Terms checkbox (the server records the accepted version).
   */
  submit: (amount: number | "", currency: string, minAmount: number, termsAccepted?: boolean) => Promise<boolean>;
  /** Leaves the result screen state (e.g. "try again" after a failure). */
  resetCheckout: () => void;
  /**
   * Shows the result of a payment confirmed without leaving the page (card, BLIK, wallets) and
   * reconciles it in the background, exactly like a redirect return.
   */
  trackConfirmedPayment: (paymentId: string, outcome: "succeeded" | "processing") => void;
}

/**
 * Checkout plumbing for the tip gate (SupportModal): per-currency minimums, the
 * create-intent call, the Stripe return-URL handling and the background reconciliation loop.
 */
export function useCheckoutFlow(options: UseCheckoutFlowOptions): UseCheckoutFlowResult {
  const { tx } = options;

  const toast = useToast();
  const { userId } = useAuth();
  const { user } = useUser();
  const userEmail = user?.primaryEmailAddress?.emailAddress;
  const { open: openAuthModal } = useAuthModal();
  const searchParams = useSearchParams();
  const queryClient = useQueryClient();

  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [clientSecret, setClientSecret] = useState<string | null>(null);
  const [paymentMethodTypes, setPaymentMethodTypes] = useState<string[]>([]);
  const [paymentId, setPaymentId] = useState<string | null>(null);
  const [paymentUiStatus, setPaymentUiStatus] = useState<TipUiStatus | null>(null);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  // True once a confirmed-success screen has been shown. Drives the full reload on close so
  // server-rendered supporter state (e.g. the comment Patron badge) is fresh.
  const [paymentSucceeded, setPaymentSucceeded] = useState(false);
  const [minimums, setMinimums] = useState<Record<SupportedCurrency, number>>(MIN_PAYMENT_BY_CURRENCY);

  useEffect(() => {
    fetch("/api/payment-settings", { cache: "no-store" })
      .then((response) => (response.ok ? response.json() : null))
      .then((data) => {
        if (!data?.limits) return;
        const next = { ...MIN_PAYMENT_BY_CURRENCY } as Record<SupportedCurrency, number>;
        for (const currency of SUPPORTED_CURRENCIES) {
          const min = Number(data.limits[currency]?.minAmount);
          if (Number.isFinite(min) && min > 0) next[currency] = min;
        }
        setMinimums(next);
      })
      .catch((error) => logger.warn("[TipFlow] Failed to fetch payment minimums:", error))
      .finally(() => setIsInitialLoading(false));
  }, []);

  // Background reconciliation shared by the redirect return and in-page confirmations: the status
  // endpoint retrieves the PaymentIntent from Stripe and runs fulfillPayment() when needed.
  // It never downgrades an already-shown success; it only upgrades a "processing" screen to
  // success (or surfaces a real failure).
  const stopTrackingRef = useRef<(() => void) | null>(null);
  const startTracking = useCallback((trackedPaymentId: string, redirectSucceeded: boolean) => {
    stopTrackingRef.current?.();
    let interval: ReturnType<typeof setInterval> | undefined;
    let cancelled = false;
    let attempts = 0;
    const maxAttempts = 10;

    const reconcile = async (): Promise<boolean> => {
      attempts++;
      try {
        const res = await fetch(`/api/payments/${encodeURIComponent(trackedPaymentId)}`, { cache: "no-store" });
        if (!res.ok) throw new Error(`Status check failed (${res.status})`);
        const data = await res.json();
        const nextStatus = (data.uiStatus as TipUiStatus | undefined) ?? null;
        const isTerminal = nextStatus === "SUCCEEDED" || nextStatus === "FAILED" || nextStatus === "REFUNDED";

        if (cancelled) return true;

        if (nextStatus === "SUCCEEDED") {
          setPaymentSucceeded(true);
          setIsSyncing(false);
          setPaymentUiStatus("SUCCEEDED");
          return true;
        }

        if (!redirectSucceeded) {
          // Only a not-yet-confirmed (async) flow may still change the visible message.
          if (isTerminal || attempts >= maxAttempts) {
            setIsSyncing(false);
            setPaymentUiStatus(nextStatus ?? "TIMED_OUT");
            return true;
          }
          setPaymentUiStatus(nextStatus ?? "PROCESSING");
          return false;
        }

        // Already showing success: keep quietly reconciling until it is recorded so the
        // on-close reload reflects it, but never change the copy.
        return isTerminal || attempts >= maxAttempts;
      } catch (e) {
        logger.error("[TipFlow] Reconcile error", e);
        if (cancelled) return true;
        if (attempts >= maxAttempts) {
          if (!redirectSucceeded) {
            setIsSyncing(false);
            setPaymentUiStatus((current) => current ?? "TIMED_OUT");
          }
          return true;
        }
        return false;
      }
    };

    reconcile().then((done) => {
      if (done || cancelled) return;
      interval = setInterval(async () => {
        const finished = await reconcile();
        if (finished && interval) clearInterval(interval);
      }, 2000);
    });

    const stop = () => {
      cancelled = true;
      if (interval) clearInterval(interval);
    };
    stopTrackingRef.current = stop;
    return stop;
  }, []);

  useEffect(() => () => stopTrackingRef.current?.(), []);

  const showOutcome = useCallback(
    (trackedPaymentId: string, outcome: "succeeded" | "processing") => {
      // This attempt is finished: the next tip starts a new one.
      storeAttemptId(null);
      setIsSuccess(true);
      setPaymentId(trackedPaymentId);
      queryClient.invalidateQueries();
      if (outcome === "succeeded") {
        setPaymentUiStatus("SUCCEEDED");
        setPaymentSucceeded(true);
        setIsSyncing(false);
      } else {
        setPaymentUiStatus("PROCESSING");
        setIsSyncing(true);
      }
      return startTracking(trackedPaymentId, outcome === "succeeded");
    },
    [queryClient, startTracking],
  );

  const trackConfirmedPayment = useCallback(
    (trackedPaymentId: string, outcome: "succeeded" | "processing") => {
      showOutcome(trackedPaymentId, outcome);
    },
    [showOutcome],
  );

  // Stripe return-URL handling: trust Stripe's own redirect_status for the visible message and
  // reconcile in the background. "succeeded" (or no param, as on a plain card confirmation)
  // shows the thank-you at once; async methods that come back "pending"/"processing" get a
  // neutral processing screen until the backend confirms.
  useEffect(() => {
    const returnedPaymentId = searchParams.get("payment_id");
    if (searchParams.get("success") !== "true" || !returnedPaymentId) return;

    const redirectStatus = searchParams.get("redirect_status");
    if (redirectStatus === "failed") {
      // Stripe says this attempt failed; the intent can still be paid, so the attempt is kept.
      setIsSuccess(true);
      setPaymentId(returnedPaymentId);
      setIsSyncing(false);
      setPaymentUiStatus("FAILED");
      return;
    }

    const redirectSucceeded = redirectStatus === "succeeded" || redirectStatus === null;
    return showOutcome(returnedPaymentId, redirectSucceeded ? "succeeded" : "processing");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams]);

  const handleRetryStatusCheck = useCallback(async () => {
    if (!paymentId) return;
    setIsSyncing(true);
    try {
      const res = await fetch(`/api/payments/${encodeURIComponent(paymentId)}`, { cache: "no-store" });
      if (!res.ok) throw new Error(`Status check failed (${res.status})`);
      const data = await res.json();
      const nextStatus = (data.uiStatus as TipUiStatus | undefined) ?? null;
      setPaymentUiStatus(nextStatus ?? "TIMED_OUT");
      if (nextStatus === "SUCCEEDED") setPaymentSucceeded(true);
    } catch (e) {
      logger.error("[TipFlow] Manual status check error", e);
      setPaymentUiStatus("TIMED_OUT");
    } finally {
      setIsSyncing(false);
    }
  }, [paymentId]);

  // Leaving the result screen: after a confirmed payment, a full reload to the clean URL so every
  // server-rendered surface reflects it. Otherwise only Stripe's return params are stripped, and
  // shallowly: a router.replace re-renders the whole page on the server and drops the open video.
  const closeSuccessAndSync = useCallback(() => {
    if (paymentSucceeded) {
      window.location.replace(window.location.pathname);
      return;
    }
    const params = new URLSearchParams(window.location.search);
    const hadReturnParams = STRIPE_RETURN_PARAMS.some((key) => params.has(key));
    if (!hadReturnParams) return;
    STRIPE_RETURN_PARAMS.forEach((key) => params.delete(key));
    const query = params.toString();
    try {
      window.history.replaceState(window.history.state, "", `${window.location.pathname}${query ? `?${query}` : ""}`);
    } catch {
      // Cosmetic; the gate is already closed.
    }
  }, [paymentSucceeded]);

  const resetCheckout = useCallback(() => {
    stopTrackingRef.current?.();
    setIsSuccess(false);
    setIsSyncing(false);
    setPaymentUiStatus(null);
  }, []);

  const requestIntent = useCallback(async (amountMinor: number, currency: string, requestId: string, termsAccepted: boolean) => {
    const response = await fetch("/api/checkout/create-intent", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        amountMinor,
        currency,
        requestId,
        ...(termsAccepted ? { acceptedTermsVersion: LEGAL_DOCUMENTS_VERSION } : {}),
      }),
      cache: "no-store",
    });
    return { response, data: await response.json().catch(() => null) };
  }, []);

  const submit = useCallback(
    async (amount: number | "", currency: string, minAmount: number, termsAccepted = false) => {
      if (!userId) {
        openAuthModal("sign-in");
        return false;
      }
      if (!amount || amount < minAmount) {
        toast(
          tx("Minimalna kwota napiwku to {0} {1}", "Minimum tip amount is {0} {1}", minAmount, currency),
          "error",
        );
        return false;
      }

      try {
        const normalizedCurrency = currency.toUpperCase();
        const amountMinor = Math.round(Number(amount) * 100);
        let requestId = readAttemptId() ?? crypto.randomUUID();
        storeAttemptId(requestId);

        let { response, data } = await requestIntent(amountMinor, normalizedCurrency, requestId, termsAccepted);
        if (data?.terminal) {
          // The stored attempt is finished (paid, failed to start, canceled): start a new one.
          requestId = crypto.randomUUID();
          storeAttemptId(requestId);
          ({ response, data } = await requestIntent(amountMinor, normalizedCurrency, requestId, termsAccepted));
        }

        if (data?.clientSecret) {
          setClientSecret(data.clientSecret);
          setPaymentMethodTypes(Array.isArray(data.paymentMethodTypes) ? data.paymentMethodTypes : []);
          setPaymentId(data.paymentId || null);
          return true;
        }

        if (response.status === 401 || String(data?.error).includes("AUTH_REQUIRED")) {
          toast(tx("Twoja sesja wygasła. Zaloguj się ponownie.", "Your session has expired. Please sign in again."), "error");
          openAuthModal("sign-in");
        } else if (data?.error === "PAYMENT_IN_PROGRESS") {
          toast(
            tx("Ten napiwek jest właśnie opłacany (np. czeka na potwierdzenie w banku). Dokończ go albo spróbuj za kilka minut.", "This tip is being paid right now (e.g. waiting for your bank). Finish it or try again in a few minutes."),
            "error",
          );
        } else {
          toast(
            tx("Nie udało się rozpocząć płatności. Spróbuj ponownie za chwilę.", "The payment could not be started. Please try again in a moment."),
            "error",
          );
        }
      } catch (error: unknown) {
        logger.error("[TipFlow] Payment error", error);
        toast(
          tx("Błąd połączenia z systemem płatności. Spróbuj odświeżyć stronę.", "Payment system connection error. Please refresh the page."),
          "error",
        );
      }
      return false;
    },
    [userId, openAuthModal, toast, tx, requestIntent],
  );

  return {
    userId,
    userEmail,
    isInitialLoading,
    minimums,
    clientSecret,
    paymentMethodTypes,
    paymentId,
    paymentUiStatus,
    isSuccess,
    isSyncing,
    handleRetryStatusCheck,
    closeSuccessAndSync,
    submit,
    resetCheckout,
    trackConfirmedPayment,
  };
}

import { escapeHtml } from "./email-content";
import type { EmailTemplateDefinition } from "./email-template-registry";

/** `{{ name }}` placeholders; the name is what the registry calls a variable key. */
const PLACEHOLDER = /\{\{\s*([A-Za-z0-9_]+)\s*\}\}/g;

export function findPlaceholders(text: string | null | undefined): string[] {
  if (!text) return [];
  const found = new Set<string>();
  for (const match of text.matchAll(PLACEHOLDER)) found.add(match[1]);
  return [...found];
}

export type TemplateVariableProblems = {
  /** Placeholders the template uses that this kind of email does not have. */
  unknown: string[];
  /** Variables this kind of email needs that a language version leaves out. */
  missingRequired: string[];
};

/**
 * Checks every field of a template against its definition. A required variable must appear in the
 * body of each language version that is present (subject alone does not carry a link).
 */
export function validateTemplateVariables(
  definition: EmailTemplateDefinition,
  fields: { subject: string; html: string; subjectEn?: string | null; htmlEn?: string | null },
): TemplateVariableProblems {
  const allowed = new Set<string>(definition.variables);
  const used = new Set<string>([
    ...findPlaceholders(fields.subject),
    ...findPlaceholders(fields.html),
    ...findPlaceholders(fields.subjectEn),
    ...findPlaceholders(fields.htmlEn),
  ]);
  const unknown = [...used].filter((key) => !allowed.has(key)).sort();

  const missing = new Set<string>();
  const bodies = [fields.html, ...(fields.htmlEn ? [fields.htmlEn] : [])];
  for (const key of definition.required) {
    for (const body of bodies) {
      if (!findPlaceholders(body).includes(key)) missing.add(key);
    }
  }
  return { unknown, missingRequired: [...missing].sort() };
}

function substitute(template: string, values: Record<string, string>, encode: (value: string) => string) {
  // An unknown or empty placeholder renders as nothing: never `{{x}}` in front of a recipient.
  return template.replace(PLACEHOLDER, (_, key: string) => encode(values[key] ?? ""));
}

/**
 * HTML body: every value is escaped, so a nickname like `<a href=…>` arrives as text, not markup.
 * URLs are escaped too (`&` → `&amp;` is the correct form inside an href attribute).
 */
export function renderHtml(template: string, values: Record<string, string>): string {
  return substitute(template, values, escapeHtml);
}

/** Subject: plain text for a header, so no escaping, but no line breaks or control characters. */
export function renderSubject(template: string, values: Record<string, string>): string {
  return toHeaderText(substitute(template, values, (value) => value));
}

export function toHeaderText(value: string): string {
  // eslint-disable-next-line no-control-regex
  return value.replace(/[\u0000-\u001f\u007f]+/g, " ").replace(/\s{2,}/g, " ").trim();
}

// Guest-only, read-only load profile for www.pawelperfect.com (k6).
// Runs ON the server against http://127.0.0.1:3000 (never through Cloudflare). See README.md.
//
// Env:
//   TARGET     journey | home | sidebar | comments | media | thumb   (default journey)
//   RATE       iterations per second (constant arrival rate)        (default 2)
//   DURATION   e.g. 60s                                              (default 60s)
//   ITERATIONS if set: exactly this many iterations, one VU, sequential (used for query counting)
//   VIDEO_ID   id of a PUBLISHED, PUBLIC video without an upcoming premiere (required)
//   BASE       default http://127.0.0.1:3000
//   HOST_HEADER default www.pawelperfect.com
//   LOCALE     default pl
//   OUT        summary JSON path inside the container (default /out/summary.json)
import http from "k6/http";
import { Rate, Counter } from "k6/metrics";

const BASE = __ENV.BASE || "http://127.0.0.1:3000";
const HOST = __ENV.HOST_HEADER || "www.pawelperfect.com";
const VIDEO_ID = __ENV.VIDEO_ID;
const TARGET = __ENV.TARGET || "journey";
const RATE = Number(__ENV.RATE || 2);
const DURATION = __ENV.DURATION || "60s";
const LOCALE = __ENV.LOCALE || "pl";
const ITERATIONS = __ENV.ITERATIONS ? Number(__ENV.ITERATIONS) : 0;
// Marks every request (and every VideoPlaybackSession row it creates, via userAgentHash) as test traffic.
const UA = "pp-loadtest/1";

if (!VIDEO_ID) throw new Error("VIDEO_ID is required");

const serverErrors = new Rate("server_errors"); // 5xx or no response
const unexpected = new Counter("unexpected_status"); // anything that is not the expected status

const EPS = ["home", "sidebar", "comments", "media", "thumb"];
const thresholds = {
  // Hard safety fuse: more than 2% 5xx/timeouts aborts the run (evaluated after 10 s).
  server_errors: [{ threshold: "rate<0.02", abortOnFail: true, delayAbortEval: "10s" }],
};
// Dummy thresholds so per-endpoint percentiles appear in the summary JSON.
for (const ep of EPS) thresholds[`http_req_duration{ep:${ep}}`] = ["max>=0"];

const vus = Math.max(4, Math.min(150, Math.ceil(RATE * (TARGET === "journey" ? 3 : 1.5))));

export const options = {
  discardResponseBodies: true,
  summaryTrendStats: ["avg", "min", "med", "p(90)", "p(95)", "p(99)", "max"],
  thresholds,
  scenarios: ITERATIONS
    ? { load: { executor: "per-vu-iterations", vus: 1, iterations: ITERATIONS, maxDuration: "5m" } }
    : {
        load: {
          executor: "constant-arrival-rate",
          rate: RATE,
          timeUnit: "1s",
          duration: DURATION,
          preAllocatedVUs: vus,
          // Capped so k6 fits its 256 MB limit; running out of VUs shows up as dropped_iterations,
          // which only happens once responses are already slow (= the server is saturated).
          maxVUs: Math.min(150, vus * 2),
          gracefulStop: "5s",
        },
      },
};

// One fake client address per iteration, from 198.18.0.0/15 (RFC 2544, reserved for benchmarking).
// The app trusts CF-Connecting-IP (TRUST_CF_CONNECTING_IP=true behind the tunnel), so every iteration
// looks like a different new visitor, exactly like real traffic; per-IP rate limits behave as in production.
function fakeIp() {
  const a = 18 + Math.floor(Math.random() * 2);
  return `198.${a}.${Math.floor(Math.random() * 256)}.${1 + Math.floor(Math.random() * 254)}`;
}

function params(ep, ip, accept) {
  return {
    headers: {
      Host: HOST,
      "User-Agent": UA,
      "CF-Connecting-IP": ip,
      "X-Forwarded-Proto": "https",
      "Accept-Language": LOCALE === "pl" ? "pl-PL,pl;q=0.9" : "en-US,en;q=0.9",
      "Accept-Encoding": "gzip, br",
      Accept: accept || "application/json",
    },
    tags: { ep },
    redirects: 0,
    timeout: "30s",
  };
}

const REQ = {
  home: (ip) => ["GET", `${BASE}/${LOCALE}`, null, params("home", ip, "text/html,application/xhtml+xml")],
  sidebar: (ip) => ["GET", `${BASE}/api/channel/sidebar?currentVideoId=${VIDEO_ID}`, null, params("sidebar", ip)],
  comments: (ip) => ["GET", `${BASE}/api/comments?videoId=${VIDEO_ID}&sortBy=newest&limit=20`, null, params("comments", ip)],
  media: (ip) => ["GET", `${BASE}/api/media-source/${VIDEO_ID}`, null, params("media", ip)],
  thumb: (ip) => ["GET", `${BASE}/api/videos/${VIDEO_ID}/thumbnail`, null, params("thumb", ip, "image/avif,image/webp,*/*")],
};

function record(res) {
  serverErrors.add(res.status === 0 || res.status >= 500);
  if (res.status !== 200) unexpected.add(1, { status: String(res.status) });
}

export default function () {
  const ip = fakeIp();
  if (TARGET === "journey") {
    // What one new guest's first page view costs the origin: the SSR page first, then the
    // browser's parallel API calls (sidebar, comments, playback plan, one thumbnail via the proxy).
    record(http.request(...REQ.home(ip)));
    const rs = http.batch([REQ.sidebar(ip), REQ.comments(ip), REQ.media(ip), REQ.thumb(ip)]);
    for (const r of rs) record(r);
    return;
  }
  const make = REQ[TARGET];
  if (!make) throw new Error(`unknown TARGET ${TARGET}`);
  record(http.request(...make(ip)));
}

export function handleSummary(data) {
  return { [__ENV.OUT || "/out/summary.json"]: JSON.stringify(data) };
}

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

const read = (file: string) => readFileSync(join(process.cwd(), file), "utf8");
const css = read("app/globals.css");

function token(name: string): string {
  const match = css.match(new RegExp(String.raw`${name}:\s*(#[0-9a-fA-F]{6})\b`));
  if (!match) throw new Error(`token ${name} not found`);
  return match[1];
}
function luminance(hex: string): number {
  const channel = (i: number) => {
    const v = parseInt(hex.slice(1 + i * 2, 3 + i * 2), 16) / 255;
    return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * channel(0) + 0.7152 * channel(1) + 0.0722 * channel(2);
}
function contrast(a: string, b: string): number {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}

describe("accessibility audit fixes: contrast of controls and focus (A15-A17)", () => {
  const surfaces = ["--chan-card", "--chan-nav", "--chan-surface"].map((name) => [name, token(name)] as const);

  it.each(surfaces)("A15: the focus ring has at least 3:1 on %s", (_name, bg) => {
    expect(contrast(token("--chan-focus-ring"), bg)).toBeGreaterThanOrEqual(3);
  });

  it("A15: the global focus rules use the opaque ring token, not a translucent blue", () => {
    expect(css).not.toContain("rgba(37, 99, 235, .45)");
    expect(css.match(/outline: 3px solid var\(--chan-focus-ring\)/g)?.length).toBe(2);
  });

  it("A15: light checkout buttons do not use the gold ring (1.7:1 on white)", () => {
    const module = read("app/components/premium-pass/premium-pass.module.css");
    expect(module).toMatch(/\.inkBtn:focus-visible, \.lineBtn:focus-visible, \.ghostBtn:focus-visible \{ outline: 3px solid var\(--chan-focus-ring/);
    expect(module).not.toMatch(/\.inkBtn:focus-visible[^{]*\{[^}]*--pass-gold/);
  });

  it.each(surfaces)("A16: the field border has at least 3:1 on %s", (_name, bg) => {
    expect(contrast(token("--chan-control-border"), bg)).toBeGreaterThanOrEqual(3);
  });

  it("A16: Studio fields and the sign-in / account fields use the control border, dividers keep --chan-line", () => {
    expect(read("app/components/studio/ui.tsx")).toMatch(/inputClass =\s*"w-full rounded-xl border border-\[var\(--chan-control-border\)\]/);
    expect(read("app/components/auth/AuthFormParts.tsx")).toContain("border border-[var(--chan-control-border)] bg-[var(--chan-surface)]");
    expect(read("app/components/auth/AccountSections.tsx")).toContain("border border-[var(--chan-control-border)] bg-[var(--chan-surface)]");
  });

  it("A17: the card-number placeholder passed to Stripe has at least 4.5:1 on white", () => {
    const color = read("app/components/support/TipPayStep.tsx").match(/"::placeholder": \{ color: "(#[0-9a-fA-F]{6})" \}/)?.[1];
    expect(color).toBeTruthy();
    expect(contrast(color!, "#ffffff")).toBeGreaterThanOrEqual(4.5);
  });
});

