describe("PolutekControls: centre play / replay overlay", () => {
  beforeEach(() => {
    document.documentElement.lang = "pl";
    media.state = {
      paused: true, waiting: false, ended: false, muted: false, volume: 1, canSetVolume: true,
      canFullscreen: true, fullscreen: false, controlsVisible: true, hasCaptions: false, textTracks: [],
    };
  });
  afterEach(() => cleanup());

  // The bottom bar has its own play/pause button with the same name; the overlay is the one inside .mc-center.
  function centerButton(view: ReturnType<typeof render>) {
    const buttons = view.container.querySelectorAll<HTMLButtonElement>(".mc-center button");
    expect(buttons).toHaveLength(1);
    return buttons[0];
  }

  it("replay is the same button as play: same classes, icon only, still has an accessible name", () => {
    const playView = render(<PolutekControls />);
    const play = centerButton(playView);
    const playClasses = play.className;
    expect(playClasses).toContain("mc-hero");
    expect(play.getAttribute("aria-label")).toBe("Odtwórz");
    expect(play.querySelector('[data-testid="play-icon"]')).not.toBeNull();
    cleanup();

    media.state = { ...media.state, ended: true };
    const replayView = render(<PolutekControls />);
    const replay = centerButton(replayView);
    // Literally the same class set as play (size, circle, shadow, hover, focus ring come from it).
    expect(replay.className).toBe(playClasses);
    // Icon only: no visible text node, the name comes from aria-label (and title).
    expect(replay.textContent).toBe("");
    expect(replay.getAttribute("aria-label")).toBe("Odtwórz ponownie");
    expect(replay.getAttribute("title")).toBe("Odtwórz ponownie");
    expect(replay.querySelector('[data-testid="replay-icon"]')).not.toBeNull();
    expect(replay.querySelector('[data-testid="play-icon"]')).toBeNull();
    // Both glyphs share one icon class, so they render at one size.
    const replayIcon = replay.querySelector('[data-testid="replay-icon"]')!;
    expect(replayIcon.getAttribute("class")).toBe("mc-hero-icon");
    expect(replay.querySelector(".mc-replay-label")).toBeNull();
  });

  it("styles no separate replay variant (no pill, no label, one glyph size)", () => {
    const css = readFileSync(join(process.cwd(), "app/globals.css"), "utf8");
    const source = readFileSync(join(process.cwd(), "app/components/player/PolutekControls.tsx"), "utf8");
    for (const dead of ["mc-hero--replay", "mc-replay-label", "mc-hero-icon-wrap"]) {
      expect(css).not.toContain(dead);
      expect(source).not.toContain(dead);
    }
    expect(css.match(/\.mc-hero-icon\s*\{/g)).toHaveLength(1);
  });
});

/**
 * Cloudflare Worker: token-checked, edge-cached delivery of our own HLS from a
 * private R2 bucket (binding HLS). Deployed on the Free plan, see
 * docs/architecture/self-hosted-hls.md and docs/operations/HLS-SELF-HOSTED.md.
 *
 * URL:  https://video.pawelperfect.com/h/<exp>.<sig>/<videoId>/<version>/<file>
 *   exp  unix seconds (token expiry)
 *   sig  base64url(HMAC-SHA256(HLS_TOKEN_SECRET, "<videoId>/<version>/<exp>"))
 * A PUBLIC video's token is "<exp>.<sig>.pub" with sig over "<videoId>/<version>/<exp>/pub".
 * Tokens without ".pub" (protected videos, and every token issued before ".pub" existed) get
 * PRIVATE response headers bounded by the token's remaining life; only ".pub" tokens get the
 * long public cache (audit S09). Deploy this Worker BEFORE the app starts issuing ".pub" tokens.
 *
 * Captions (WebVTT) of the video are served under the SAME token: GET .../<version>/captions/<lang>-<sha256>.vtt
 * reads the private object videos/<videoId>/captions/<lang>-<sha256>.vtt (not inside the version folder, so a
 * re-encode keeps them; the version in the URL only has to match the token). Mirror of
 * lib/modules/media/domain/protected-caption.ts. Deploy this Worker BEFORE the app issues caption URLs.
 *
 * One token covers every file of one video version (playlists, init, segments,
 * poster), so the playlists only need RELATIVE URIs and both hls.js and native
 * Safari HLS simply inherit "/h/<exp>.<sig>/<videoId>/<version>/" - no headers,
 * cookies or manifest rewriting. The token is issued by PlaybackService only
 * after checkVideoAccess() + the premiere gate (CLAUDE.md 4.3, 4.15).
 *
 * Cache: the edge cache key is the token-less path, so one cached copy serves
 * every viewer; the token is verified on EVERY request before the cache is
 * consulted. This is access control, not DRM: a signed-in viewer can copy the
 * URL for the token lifetime.
 *
 * No dependencies, plain ES module (uploaded as-is, no build step).
 */

const ID_RE = /^[A-Za-z0-9-]{8,64}$/;
const VERSION_RE = /^[A-Za-z0-9_-]{1,32}$/;
/** Caption files: "captions/<lang>-<sha256>.vtt" (anything else below "captions/" is not served). */
const CAPTION_REST_RE = /^captions\/([a-z]{2,8}-[0-9a-f]{64}\.vtt)$/;
const REST_RE = /^[A-Za-z0-9_-]+(?:\/[A-Za-z0-9_-]+)*\.[A-Za-z0-9]{2,5}$/;

const CONTENT_TYPES = {
  m3u8: 'application/vnd.apple.mpegurl',
  m4s: 'video/iso.segment',
  mp4: 'video/mp4',
  ts: 'video/mp2t',
  vtt: 'text/vtt; charset=utf-8',
  jpg: 'image/jpeg',
  webp: 'image/webp',
};

const IMMUTABLE = 'public, max-age=31536000, immutable';
const SHORT = 'public, max-age=300';
/** Longest a client may reuse a playlist of a protected video without asking again. */
const PROTECTED_PLAYLIST_MAX_AGE = 60;

const enc = new TextEncoder();

function base64urlDecode(s) {
  const pad = '='.repeat((4 - (s.length % 4)) % 4);
  const bin = atob(s.replace(/-/g, '+').replace(/_/g, '/') + pad);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** Message that is signed for a video version; must match lib/modules/playback self-hls-token.service. */
export function tokenMessage(videoId, version, exp, isPublic = false) {
  return `${videoId}/${version}/${exp}${isPublic ? '/pub' : ''}`;
}

const TOKEN_RE = /^(\d{10})\.([A-Za-z0-9_-]{43})(\.pub)?$/;

/** Verifies "<exp>.<sig>[.pub]". Returns { exp, isPublic } or null. Constant-time compare through WebCrypto. */
export async function checkToken(secret, videoId, version, token, nowSeconds) {
  if (!secret || typeof token !== 'string') return null;
  const m = TOKEN_RE.exec(token);
  if (!m) return null;
  const exp = Number(m[1]);
  if (exp <= nowSeconds) return null;
  const isPublic = m[3] === '.pub';
  const key = await hmacKey(secret);
  const ok = await crypto.subtle.verify('HMAC', key, base64urlDecode(m[2]), enc.encode(tokenMessage(videoId, version, exp, isPublic)));
  return ok ? { exp, isPublic } : null;
}

/** Boolean form of checkToken. */
export async function verifyToken(secret, videoId, version, token, nowSeconds) {
  return (await checkToken(secret, videoId, version, token, nowSeconds)) !== null;
}

/**
 * Cache-Control sent to the CLIENT (the copy kept in the Worker's own cache is always the long
 * public one, see objectHeaders: that cache sits behind the token check). Public video: long and
 * public. Protected: private (no shared cache may keep it) and never longer than the token's
 * remaining life, so a browser copy does not outlive the access the token stood for.
 */
export function clientCacheControl(ext, token, nowSeconds) {
  if (token.isPublic) return ext === 'm3u8' ? SHORT : IMMUTABLE;
  const remaining = Math.max(0, token.exp - nowSeconds);
  const maxAge = ext === 'm3u8' ? Math.min(remaining, PROTECTED_PLAYLIST_MAX_AGE) : remaining;
  return `private, max-age=${maxAge}`;
}

/** The imported HMAC key, kept for the life of the isolate (re-imported only if the secret changes). */
let cachedKey = null;
function hmacKey(secret) {
  if (cachedKey?.secret !== secret) {
    cachedKey = { secret, key: crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['verify']) };
  }
  return cachedKey.key;
}

/** "bytes start-end/size" for an R2 object read with a range. */
export function contentRange(range, size) {
  const offset = 'suffix' in range ? Math.max(0, size - range.suffix) : (range.offset ?? 0);
  const length = 'suffix' in range ? size - offset : (range.length ?? size - offset);
  return { offset, length, header: `bytes ${offset}-${offset + length - 1}/${size}` };
}

/** Headers of the copy stored in the Worker's own edge cache (never sent as is to a protected client). */
function objectHeaders(parsed, object) {
  const headers = new Headers();
  headers.set('Content-Type', CONTENT_TYPES[parsed.ext]);
  headers.set('Cache-Control', parsed.ext === 'm3u8' ? SHORT : IMMUTABLE);
  headers.set('ETag', object.httpEtag);
  headers.set('Accept-Ranges', 'bytes');
  headers.set('X-Content-Type-Options', 'nosniff');
  return headers;
}

/** Splits "/h/<token>/<id>/<version>/<rest>" or returns null. `captionFile` is set for a caption path. */
export function parsePath(pathname) {
  const parts = pathname.split('/');
  // ['', 'h', token, id, version, ...rest]
  if (parts.length < 6 || parts[0] !== '' || parts[1] !== 'h') return null;
  const [, , token, videoId, version, ...restParts] = parts;
  const rest = restParts.join('/');
  if (!ID_RE.test(videoId) || !VERSION_RE.test(version) || !REST_RE.test(rest)) return null;
  const ext = rest.slice(rest.lastIndexOf('.') + 1).toLowerCase();
  if (!CONTENT_TYPES[ext]) return null;
  if (rest.startsWith('captions/')) {
    const caption = CAPTION_REST_RE.exec(rest);
    return caption ? { token, videoId, version, rest, ext, captionFile: caption[1] } : null;
  }
  return { token, videoId, version, rest, ext, captionFile: null };
}

function corsHeaders(request, env) {
  const origin = request.headers.get('Origin');
  const allowed = (env.ALLOWED_ORIGINS || '').split(',').map((s) => s.trim()).filter(Boolean);
  const headers = new Headers({ Vary: 'Origin' });
  if (origin && allowed.includes(origin)) {
    headers.set('Access-Control-Allow-Origin', origin);
    headers.set('Access-Control-Expose-Headers', 'Content-Length, Content-Range, Accept-Ranges');
    headers.set('Timing-Allow-Origin', origin);
  }
  return headers;
}

function plain(status, body, request, env) {
  const headers = corsHeaders(request, env);
  headers.set('Cache-Control', 'no-store');
  headers.set('Content-Type', 'text/plain; charset=utf-8');
  return new Response(body, { status, headers });
}

export default {
  async fetch(request, env, ctx) {
    const method = request.method;
    if (method === 'OPTIONS') {
      const headers = corsHeaders(request, env);
      headers.set('Access-Control-Allow-Methods', 'GET, HEAD, OPTIONS');
      headers.set('Access-Control-Allow-Headers', 'Range');
      headers.set('Access-Control-Max-Age', '86400');
      return new Response(null, { status: 204, headers });
    }
    if (method !== 'GET' && method !== 'HEAD') return plain(405, 'Method not allowed', request, env);

    const url = new URL(request.url);
    const parsed = parsePath(url.pathname);
    if (!parsed) return plain(404, 'Not found', request, env);

    const nowSeconds = Math.floor(Date.now() / 1000);
    const token = await checkToken(env.HLS_TOKEN_SECRET, parsed.videoId, parsed.version, parsed.token, nowSeconds);
    if (!token) return plain(403, 'Forbidden', request, env);

    // Captions are per video (content-hashed name), so their cache entry does not depend on the version.
    const cacheUrl = parsed.captionFile
      ? `https://${url.host}/c/${parsed.videoId}/captions/${parsed.captionFile}`
      : `https://${url.host}/c/${parsed.videoId}/${parsed.version}/${parsed.rest}`;
    const cache = caches.default;
    const range = request.headers.get('Range');
    const lookup = new Request(cacheUrl, { method: 'GET', headers: range ? { Range: range } : {} });

    let response = await cache.match(lookup);
    let cacheStatus = 'HIT';
    if (!response) {
      cacheStatus = 'MISS';
      const objectKey = parsed.captionFile
        ? `videos/${parsed.videoId}/captions/${parsed.captionFile}`
        : `videos/${parsed.videoId}/v/${parsed.version}/${parsed.rest}`;
      const fillCache = async () => {
        const object = await env.HLS.get(objectKey);
        if (object) await cache.put(new Request(cacheUrl, { method: 'GET' }), new Response(object.body, { status: 200, headers: objectHeaders(parsed, object) }));
      };
      if (method === 'HEAD') {
        // Metadata only: no body read from R2 and nothing cached.
        const object = await env.HLS.head(objectKey);
        if (!object) return plain(404, 'Not found', request, env);
        const headers = objectHeaders(parsed, object);
        headers.set('Content-Length', String(object.size));
        response = new Response(null, { status: 200, headers });
      } else if (range) {
        // Answer the range straight from R2 (no waiting for the whole object) and fill the
        // cache with the complete object in the background; the cache only stores full bodies.
        let object;
        try {
          object = await env.HLS.get(objectKey, { range: request.headers });
        } catch {
          return plain(416, 'Range not satisfiable', request, env);
        }
        if (!object) return plain(404, 'Not found', request, env);
        const headers = objectHeaders(parsed, object);
        if (object.range) {
          const r = contentRange(object.range, object.size);
          headers.set('Content-Range', r.header);
          headers.set('Content-Length', String(r.length));
          response = new Response(object.body, { status: 206, headers });
        } else {
          response = new Response(object.body, { status: 200, headers });
        }
        ctx.waitUntil(fillCache());
      } else {
        const object = await env.HLS.get(objectKey);
        if (!object) return plain(404, 'Not found', request, env);
        const full = new Response(object.body, { status: 200, headers: objectHeaders(parsed, object) });
        ctx.waitUntil(cache.put(new Request(cacheUrl, { method: 'GET' }), full.clone()));
        response = full;
      }
    }

    const out = new Response(method === 'HEAD' ? null : response.body, response);
    for (const [k, v] of corsHeaders(request, env)) out.headers.set(k, v);
    out.headers.set('X-Hls-Cache', cacheStatus);
    out.headers.set('Cache-Control', clientCacheControl(parsed.ext, token, nowSeconds));
    return out;
  },
};

/**
 * pp-watchdog: external watchdog of serwerek (Cloudflare Workers Free, cron trigger every 5 min).
 * A monitor on the server dies with the server; this one runs on Cloudflare's edge.
 *
 * Every 5 minutes (scheduled):
 *   - www:      GET https://www.pawelperfect.com/api/health  -> 200
 *   - video:    GET https://video.pawelperfect.com/           -> 404 from the HLS Worker (Worker alive, R2 path served)
 *   - support:  GET https://support.pawelperfect.com/         -> 302 to Cloudflare Access
 *   - heartbeat: health.sh on the server POSTs /ping every 5 min; no ping for 15 min = the server is gone
 *                (dead man's switch); a WARN reported for 30 min is escalated here too (second channel).
 * A check alerts after 2 failed runs in a row (no e-mail for a blip), again every 6 h while failing, and once
 * when it recovers. E-mail through Resend, at most MAX_ALERTS_PER_DAY a day (the app shares the Resend quota).
 * State: D1 (binding DB). Free-plan budget: 288 cron runs + 288 pings a day.
 *
 * HTTP (all need "Authorization: Bearer <PING_TOKEN>"):
 *   POST /ping        body "OK" or "WARN <issues>"  (health.sh)
 *   POST /run         run the checks now, returns the states (testing)
 *   POST /test-alert  send one test e-mail
 *   GET  /status      current states as JSON
 * Deploy: node workers/pp-watchdog/deploy.mjs (docs/operations/SERWEREK.md, section 25).
 */

const CHECKS = [
  { name: 'www', url: 'https://www.pawelperfect.com/api/health', expect: (r) => r.status === 200 },
  { name: 'video', url: 'https://video.pawelperfect.com/', expect: (r) => r.status === 404 },
  {
    name: 'support',
    url: 'https://support.pawelperfect.com/',
    expect: (r) => r.status === 302 && (r.headers.get('location') || '').includes('cloudflareaccess.com'),
  },
];
const FAILS_BEFORE_ALERT = 2;
const REALERT_MS = 6 * 60 * 60 * 1000;
const PING_STALE_MS = 15 * 60 * 1000;
const WARN_ESCALATE_MS = 30 * 60 * 1000;
const MAX_ALERTS_PER_DAY = 20;

const SCHEMA = [
  `CREATE TABLE IF NOT EXISTS check_state (name TEXT PRIMARY KEY, ok INTEGER NOT NULL, fails INTEGER NOT NULL,
     since INTEGER NOT NULL, last_alert INTEGER, detail TEXT, checked_at INTEGER NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS ping (source TEXT PRIMARY KEY, at INTEGER NOT NULL, status TEXT NOT NULL,
     warn_since INTEGER)`,
  `CREATE TABLE IF NOT EXISTS alert_day (day TEXT PRIMARY KEY, sent INTEGER NOT NULL)`,
];

async function ensureSchema(db) {
  await db.batch(SCHEMA.map((sql) => db.prepare(sql)));
}

function authorized(request, env) {
  const header = request.headers.get('authorization') || '';
  return env.PING_TOKEN && header === `Bearer ${env.PING_TOKEN}`;
}

async function probe(check) {
  try {
    const response = await fetch(check.url, {
      redirect: 'manual',
      headers: { 'user-agent': 'pp-watchdog/1 (+https://www.pawelperfect.com)' },
      signal: AbortSignal.timeout(10_000),
      cf: { cacheTtl: 0 },
    });
    return { ok: check.expect(response), detail: `HTTP ${response.status}` };
  } catch (error) {
    return { ok: false, detail: `error ${error && error.name ? error.name : 'fetch'}` };
  }
}

/** Results of all checks, including the heartbeat ones derived from the last ping. */
async function evaluate(env, now) {
  const results = await Promise.all(CHECKS.map(async (check) => ({ name: check.name, ...(await probe(check)) })));
  const ping = await env.DB.prepare('SELECT at, status, warn_since FROM ping WHERE source = ?').bind('serwerek').first();
  if (!ping) {
    results.push({ name: 'heartbeat', ok: false, detail: 'no ping received yet' });
  } else {
    const age = now - ping.at;
    results.push({ name: 'heartbeat', ok: age <= PING_STALE_MS, detail: `last ping ${Math.round(age / 60000)} min ago` });
    const warnFor = ping.warn_since ? now - ping.warn_since : 0;
    results.push({
      name: 'server-warn',
      ok: !(ping.status.startsWith('WARN') && warnFor >= WARN_ESCALATE_MS),
      detail: ping.status.slice(0, 300),
    });
  }
  return results;
}

async function sendMail(env, subject, text, now) {
  const day = new Date(now).toISOString().slice(0, 10);
  const row = await env.DB.prepare('SELECT sent FROM alert_day WHERE day = ?').bind(day).first();
  if ((row ? row.sent : 0) >= MAX_ALERTS_PER_DAY) return false;
  const response = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: { Authorization: `Bearer ${env.RESEND_API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ from: env.ALERT_FROM, to: [env.ALERT_TO], subject, text, tags: [{ name: 'kind', value: 'watchdog' }] }),
  });
  if (!response.ok) return false;
  await env.DB.prepare('INSERT INTO alert_day (day, sent) VALUES (?, 1) ON CONFLICT(day) DO UPDATE SET sent = sent + 1').bind(day).run();
  await env.DB.prepare('DELETE FROM alert_day WHERE day < ?').bind(new Date(now - 7 * 86400000).toISOString().slice(0, 10)).run();
  return true;
}

/** Applies one result to the stored state and decides about an e-mail. Exported for tests. */
export function nextState(previous, result, now) {
  const state = previous
    ? { ...previous }
    : { name: result.name, ok: 1, fails: 0, since: now, last_alert: null, detail: null, checked_at: now };
  let mail = null;
  if (result.ok) {
    const wasAlerting = !state.ok && state.fails >= FAILS_BEFORE_ALERT && state.last_alert;
    if (!state.ok) state.since = now;
    state.ok = 1;
    state.fails = 0;
    if (wasAlerting) {
      mail = { subject: `[pp-watchdog] OK again: ${result.name}`, text: `${result.name} is OK again (${result.detail}).` };
      state.last_alert = null;
    }
  } else {
    if (state.ok) state.since = now;
    state.ok = 0;
    state.fails += 1;
    const due = state.fails >= FAILS_BEFORE_ALERT && (!state.last_alert || now - state.last_alert >= REALERT_MS);
    if (due) {
      mail = {
        subject: `[pp-watchdog] DOWN: ${result.name}`,
        text: `${result.name} failing since ${new Date(state.since).toISOString()} (${state.fails} checks in a row): ${result.detail}.\nNext reminder in 6 h if it stays down.`,
      };
      state.last_alert = now;
    }
  }
  state.detail = result.detail;
  state.checked_at = now;
  return { state, mail };
}

async function runChecks(env, now = Date.now()) {
  await ensureSchema(env.DB);
  const results = await evaluate(env, now);
  const states = [];
  for (const result of results) {
    const previous = await env.DB.prepare('SELECT * FROM check_state WHERE name = ?').bind(result.name).first();
    const { state, mail } = nextState(previous, result, now);
    if (mail && !(await sendMail(env, mail.subject, mail.text, now)) && state.last_alert === now) {
      state.last_alert = previous ? previous.last_alert : null; // not sent: try again next run
    }
    await env.DB.prepare(
      `INSERT INTO check_state (name, ok, fails, since, last_alert, detail, checked_at) VALUES (?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(name) DO UPDATE SET ok = excluded.ok, fails = excluded.fails, since = excluded.since,
         last_alert = excluded.last_alert, detail = excluded.detail, checked_at = excluded.checked_at`,
    ).bind(state.name, state.ok, state.fails, state.since, state.last_alert, state.detail, state.checked_at).run();
    states.push(state);
  }
  return states;
}

const json = (body, status = 200) => new Response(JSON.stringify(body, null, 2), { status, headers: { 'content-type': 'application/json', 'cache-control': 'no-store' } });

export default {
  async scheduled(_event, env, ctx) {
    ctx.waitUntil(runChecks(env));
  },

  async fetch(request, env) {
    const { pathname } = new URL(request.url);
    if (!authorized(request, env)) return new Response('Not found', { status: 404 });
    const now = Date.now();
    if (request.method === 'POST' && pathname === '/ping') {
      await ensureSchema(env.DB);
      const status = ((await request.text()) || 'OK').trim().slice(0, 500) || 'OK';
      await env.DB.prepare(
        `INSERT INTO ping (source, at, status, warn_since) VALUES ('serwerek', ?1, ?2, CASE WHEN ?2 LIKE 'WARN%' THEN ?1 END)
         ON CONFLICT(source) DO UPDATE SET at = ?1, status = ?2,
           warn_since = CASE WHEN ?2 LIKE 'WARN%' THEN coalesce(ping.warn_since, ?1) END`,
      ).bind(now, status).run();
      return new Response(null, { status: 204 });
    }
    if (request.method === 'POST' && pathname === '/run') return json(await runChecks(env, now));
    if (request.method === 'POST' && pathname === '/test-alert') {
      await ensureSchema(env.DB);
      const sent = await sendMail(env, '[pp-watchdog] test alert', `Test e-mail from pp-watchdog at ${new Date(now).toISOString()}. No action needed.`, now);
      return json({ sent }, sent ? 200 : 502);
    }
    if (request.method === 'GET' && pathname === '/status') {
      await ensureSchema(env.DB);
      const { results } = await env.DB.prepare('SELECT * FROM check_state ORDER BY name').all();
      const ping = await env.DB.prepare('SELECT * FROM ping').all();
      return json({ checks: results, ping: ping.results });
    }
    return new Response('Not found', { status: 404 });
  },
};

/**
 * PP Support: warstwa marki przed panelem (support.pawelperfect.com).
 * Wstrzykuje CSS/JS i ikony do stron HTML panelu oraz serwuje wlasne zasoby pod /pp-support/*.
 * Wszystko inne (API, websockety, ingress poczty, zasoby statyczne) idzie 1:1 do origin.
 * Kill switch: binding BRAND_ENABLED=0 (node workers/support-brand/deploy.mjs --disable) = czysty pass-through.
 * Dane (zasoby, nazwa) sa doklejane przez deploy.mjs w miejsce znacznika danych nizej.
 */
const DATA = __DATA__;
const SKIP = /^\/(api|auth|cable|rails|webhooks|vite|packs|assets|audio|videos|pp-support)(\/|$)/;

function b64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function serveAsset(path, method) {
  const a = DATA.assets[path];
  if (!a || (method !== 'GET' && method !== 'HEAD')) return new Response('Not found', { status: 404 });
  const body = method === 'HEAD' ? null : a.text !== undefined ? a.text : b64ToBytes(a.b64);
  return new Response(body, { headers: { 'content-type': a.type, 'cache-control': 'public, max-age=300', 'x-content-type-options': 'nosniff' } });
}

function headHtml() {
  const v = DATA.version;
  const b = DATA.brand;
  return [
    `<script>window.PP_BRAND=${JSON.stringify({ name: b.name, shortName: b.shortName, termsUrl: b.termsUrl, privacyUrl: b.privacyUrl })};</script>`,
    `<link rel="icon" type="image/svg+xml" href="/pp-support/logo-thumbnail.svg?v=${v}">`,
    `<link rel="icon" type="image/png" sizes="32x32" href="/pp-support/icon-32.png?v=${v}">`,
    `<link rel="icon" type="image/png" sizes="96x96" href="/pp-support/icon-96.png?v=${v}">`,
    `<link rel="apple-touch-icon" sizes="180x180" href="/pp-support/icon-180.png?v=${v}">`,
    `<link rel="manifest" href="/pp-support/manifest.webmanifest?v=${v}" crossorigin="use-credentials">`,
    `<meta name="theme-color" content="${b.accent}">`,
    `<link rel="stylesheet" href="/pp-support/brand.css?v=${v}">`,
    `<script src="/pp-support/brand.js?v=${v}" defer></script>`,
  ].join('');
}

export default {
  async fetch(request, env) {
    if (env.BRAND_ENABLED === '0') return fetch(request);
    const url = new URL(request.url);
    if (url.pathname.startsWith('/pp-support/')) return serveAsset(url.pathname, request.method);
    const accept = request.headers.get('accept') || '';
    if (request.method !== 'GET' || SKIP.test(url.pathname) || !accept.includes('text/html')) return fetch(request);

    const res = await fetch(request);
    if (!(res.headers.get('content-type') || '').includes('text/html')) return res;
    const rewritten = new HTMLRewriter()
      .on('link[rel~="icon"], link[rel="apple-touch-icon"], link[rel="manifest"], meta[name="msapplication-TileImage"], meta[name="theme-color"], meta[name="msapplication-TileColor"]', { element: (e) => e.remove() })
      .on('meta[name="description"]', { element: (e) => e.setAttribute('content', `${DATA.brand.name}: wspolna skrzynka obslugi klienta.`) })
      .on('head', { element: (e) => e.append(headHtml(), { html: true }) })
      .transform(res);
    const out = new Response(rewritten.body, rewritten);
    out.headers.set('x-pp-brand', DATA.version);
    return out;
  },
};

/**
 * Cloudflare Email Worker: inbound support mail -> PP Support (self-hosted) + archive copy.
 *
 * Contract (docs/architecture/support-center.md):
 *  1. POST the raw RFC822 message to the PP Support Action Mailbox relay ingress
 *     (basic auth + Cloudflare Access service token, because the host sits behind Access).
 *  2. ALWAYS forward a copy to the archive address (verified destination), with the header
 *     X-Support-Ingest: ok | failed:<reason>, so a failed ingest still leaves the mail in the archive.
 *  3. Never bounce because PP Support is down: an Email Worker cannot send a temporary (4xx) failure,
 *     a reject would be permanent. The archive copy is the safety net; re-ingest is in the runbook.
 *
 * Bindings: SUPPORT_INGEST_URL, INGEST_PASSWORD (secret), ACCESS_CLIENT_ID,
 * ACCESS_CLIENT_SECRET (secret), ARCHIVE_TO.
 */
const MAX_RAW_BYTES = 25 * 1024 * 1024;

// Recipients that become PP Support conversations. Everything else that reaches the catch-all
// (guessed addresses, spam to random@...) is only forwarded to the archive, so the inbox stays clean.
// Replies to conversations arrive at reply+<uuid>@inbound.<domain> and the forward address at
// <uuid>@inbound.<domain>: any address on an `inbound.` subdomain is ingested.
const INGEST_LOCAL_PARTS = new Set(['support', 'hello']);

// PP Support matches a message to its inbox by the To/Cc addresses and the X-Original-To header
// (EmailChannelFinder). The inbox channel address is support@pawelperfect.com, so mail that arrived for
// hello@ or for the .pl aliases gets this header prepended; the stored message otherwise stays untouched.
export const CHANNEL_ADDRESS = 'support@pawelperfect.com';

export function withChannelHeader(raw) {
  const head = new TextEncoder().encode(`X-Original-To: ${CHANNEL_ADDRESS}
`);
  const body = new Uint8Array(raw);
  const out = new Uint8Array(head.length + body.length);
  out.set(head, 0);
  out.set(body, head.length);
  return out;
}

export function shouldIngest(to) {
  const at = String(to || '').toLowerCase().lastIndexOf('@');
  if (at < 1) return false;
  const local = String(to).toLowerCase().slice(0, at);
  const domain = String(to).toLowerCase().slice(at + 1);
  if (domain.startsWith('inbound.')) return true;
  return INGEST_LOCAL_PARTS.has(local);
}

async function ingest(env, raw) {
  const auth = 'Basic ' + btoa(`actionmailbox:${env.INGEST_PASSWORD}`);
  let last = 'no-attempt';
  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      const res = await fetch(env.SUPPORT_INGEST_URL, {
        method: 'POST',
        headers: {
          'content-type': 'message/rfc822',
          authorization: auth,
          'CF-Access-Client-Id': env.ACCESS_CLIENT_ID,
          'CF-Access-Client-Secret': env.ACCESS_CLIENT_SECRET,
        },
        body: raw,
        signal: AbortSignal.timeout(20000),
      });
      if (res.ok) return 'ok';
      last = `http-${res.status}`;
      // 4xx other than 408/429 will not get better by retrying (bad credentials, malformed mail).
      if (res.status < 500 && res.status !== 408 && res.status !== 429) break;
    } catch (e) {
      last = `error-${e && e.name ? e.name : 'unknown'}`;
    }
    await new Promise((r) => setTimeout(r, 1500));
  }
  return `failed:${last}`;
}

export default {
  async email(message, env) {
    let status;
    if (!shouldIngest(message.to)) {
      status = 'skipped:unlisted-recipient';
    } else if (message.rawSize > MAX_RAW_BYTES) {
      status = 'failed:too-large';
    } else {
      const raw = await new Response(message.raw).arrayBuffer();
      const domain = String(message.to || '').toLowerCase().split('@')[1] || '';
      status = await ingest(env, domain.startsWith('inbound.') ? raw : withChannelHeader(raw));
    }
    if (status.startsWith('failed')) console.error(`support-mail-ingest ${status} from=${message.from} to=${message.to}`);
    await message.forward(env.ARCHIVE_TO, new Headers({ 'X-Support-Ingest': status }));
  },
};
